    #[test]
    fn reset_completion_watch_gates_on_had_effect() {
        // Same unification, the watchdog-reset half -- the exact consumer
        // the Farm arm was missing entirely until 4d9180252f added it back
        // by hand. This is the function both arms now call.
        let uid = Uid(NonZeroU64::new(80).unwrap());
        let mut stuck_watch: HashMap<Uid, f32> = HashMap::from([(uid, 12.5)]);
        reset_completion_watch(&mut stuck_watch, Some(&uid), false, "test-reason");
        assert_eq!(
            stuck_watch.get(&uid),
            Some(&12.5),
            "had_effect=false must leave the watchdog accrual untouched -- a phantom \
             completion must not read as real progress to the safety net"
        );
        reset_completion_watch(&mut stuck_watch, Some(&uid), true, "test-reason");
        assert!(
            !stuck_watch.contains_key(&uid),
            "had_effect=true must wipe the watchdog accrual -- real work is the ground-truth \
             progress signal"
        );
    }

    #[test]
    fn bedtime_prices_retries_at_the_dire_rate_and_day_does_not() {
        // The Alen sweep's sleep tail: schedule forces the want at 22:00,
        // the band still reads the healthy meter, and every retry paid the
        // full 60s (≈48 game-minutes). During the Sleep block the cadence
        // is the Dire floor — non-zero (the anti-thrash guard survives),
        // and STRICTLY shorter than the Fine-band day price.
        let cfg = common::bastion::MoodConfig::default();
        let until = 1000.0; // cooldown written at 940.0
        let healthy = (0.8f32, 0.8f32);
        let tired = (0.25f32, 0.8f32); // below rest comfort, hunger fine
        // Day, healthy bands: still cooling at +30s.
        assert!(preempt_cooldown_active(
            Some(until), 970.0, healthy.0, healthy.1, &cfg, false
        ));
        // ★ Bedtime + FULLY RESTED: still the full price — this is the arm
        // the first fix broke (slept=132/late=102: rested colonists cycling
        // bed all night on the 5s cadence the schedule's forced want opened).
        assert!(preempt_cooldown_active(
            Some(until), 970.0, healthy.0, healthy.1, &cfg, true
        ));
        // Bedtime + TIRED (below comfort): the Dire floor (5s) has lapsed.
        assert!(!preempt_cooldown_active(
            Some(until), 970.0, tired.0, tired.1, &cfg, true
        ));
        // The floor is real: 3s in, even a tired bedtime still cools.
        assert!(preempt_cooldown_active(
            Some(until), 943.0, tired.0, tired.1, &cfg, true
        ));
    }

    #[test]
    fn a_player_order_outranks_the_lane() {
        // The 44-day refusal in one assertion: an adopted farmer (farm=4,
        // mine=2) must pick the PAINTED mine job over routine farm work.
        // Tier logic only — the scorer compares priority before score, so
        // painted tier 5 vs farm tier 4 decides regardless of distance.
        let mut painted = common::bastion::WorkPriorities::in_lane(
            common::bastion::WorkType::Farm,
        )
        .get(common::bastion::WorkType::Mine);
        assert_eq!(painted, 2, "the caste that never won");
        // The scorer's lift (mirrored here as the same max expression the
        // claim loop applies): painted mine reads tier 5.
        painted = painted.max(5);
        let farm = common::bastion::WorkPriorities::in_lane(
            common::bastion::WorkType::Farm,
        )
        .get(common::bastion::WorkType::Farm);
        assert!(
            painted > farm,
            "a player order must outrank in-lane routine ({painted} vs {farm})"
        );
    }

    #[test]
    fn commitment_prefers_the_lane_and_lapses_honestly() {
        use common::bastion::WorkType as W;
        // A miner mid-window: mining reads closer, farming does not.
        let last = Some((W::Mine, 100.0));
        assert_eq!(commitment_factor(last, W::Mine, 200.0), COMMITMENT_FACTOR);
        assert_eq!(commitment_factor(last, W::Farm, 200.0), 1.0);
        // The window lapses: the preference vanishes ENTIRELY (a lapsed
        // bonus lingering at some in-between value would be a second,
        // unintended commitment tier).
        assert_eq!(
            commitment_factor(last, W::Mine, 100.0 + COMMITMENT_SECS),
            1.0
        );
        // No history — a fresh colonist scores the old formula exactly.
        assert_eq!(commitment_factor(None, W::Mine, 0.0), 1.0);
    }

    #[test]
    fn the_gathering_ring_seats_a_colony_without_stacking() {
        // The whole point of the ring is TOGETHER-BUT-NOT-STACKED: for a
        // full colony of distinct uids, every seat is distinct, every seat
        // is within the plaza's reach (radius ≤ 6), and the same uid gets
        // the same seat on every call — a regular's bench, deterministic
        // across runs.
        let anchor = Vec3::new(100, 200, 40);
        let mut seats = std::collections::HashSet::new();
        // RANK-BASED seating: the real colony that collided under mod-12
        // (fleet: gather_seats=6 of 8) must seat 8 DISTINCT — and by
        // construction ANY set up to ring size does; the 13th wraps.
        let colony = [18u64, 19, 165, 174, 175, 193, 206, 212];
        let mut sorted = colony.to_vec();
        sorted.sort_unstable();
        for u in colony {
            let rank = sorted.iter().position(|&x| x == u).unwrap();
            let a = gathering_spot(anchor, rank);
            let b = gathering_spot(anchor, rank);
            assert_eq!(a, b, "a regular's bench: same rank, same seat");
            let d = a - anchor;
            assert!(
                d.x.abs() + d.y.abs() <= 6 && d.z == 0,
                "every seat within the plaza: {d:?}"
            );
            assert!(seats.insert(a), "no two colonists in one seat: {a:?}");
        }
        assert_eq!(seats.len(), 8, "eight colonists, eight distinct seats");
        // CITY RINGS superseded the old wrap contract ("the 13th shares the
        // first bench"): the 13th villager now gets his OWN seat on the
        // first outer ring — the mega-city blob was that wrap at 44 ranks.
        assert_ne!(
            gathering_spot(anchor, 12),
            gathering_spot(anchor, 0),
            "the 13th villager seats the outer ring, not somebody's bench"
        );
    }

    #[test]
    fn an_alarm_shelter_is_born_claimed_at_home() {
        // ALARM v1's whole claim story: the shelter job never touches the
        // open board (a cry must not wait for office hours), so it must be
        // born claimed FOR the civilian, AT their bed cell, with the frozen
        // expiry riding in the kind. The self-job predicates that keep the
        // open claim loop and the orphan sweep away from it are asserted
        // against the REAL job the helper makes, not a hand-built twin.
        let mut board = JobBoard::default();
        let uid = Uid(NonZeroU64::new(9).unwrap());
        let home = Vec3::new(10, 20, 30);
        let id = board.insert_shelter_job(home, 456.5, uid);
        let job = board.jobs.get(&id).expect("job inserted");
        assert_eq!(job.claimed_by, Some(uid), "born claimed — never on the open board");
        assert_eq!(job.pos, home, "the hold happens at the civilian's own bed");
        match job.kind {
            common::bastion::JobKind::Shelter { home: h, until } => {
                assert_eq!(h, home);
                assert_eq!(until, 456.5, "expiry frozen at post time");
            },
            ref k => panic!("wrong kind: {k:?}"),
        }
        assert!(job.kind.designation().is_none(), "shelter is not paint");
        assert_eq!(job_release_class(&job.kind), "shelter");
    }

    #[test]
    fn release_decision_branch_table() {
        use ReleaseDecision::*;
        // REQ-0061: an active transaction always keeps driving.
        assert_eq!(release_decision(true, true, false, true, false), KeepDriving);
        // (ii) route exhausted + exit invalid outranks the exit legs.
        assert_eq!(release_decision(false, true, false, true, false), ExhaustedReplan);
        // (i) verified and off the route: stable-exit candidate.
        assert_eq!(release_decision(false, false, false, true, false), StableExitCandidate);
        // Verified but still ON route cells: keep driving (dismount pending).
        assert_eq!(release_decision(false, false, false, true, true), KeepDriving);
        // Nothing met: keep driving.
        assert_eq!(release_decision(false, true, true, false, false), KeepDriving);
    }

    #[test]
    fn claim_release_clears_even_when_unreachable() {
        // ITEM8-V4 route 1, RED PRE-FIX: the old gate was
        // `claimed_by_us && !unreachable`, so this exact case --
        // a job we hold, marked unreachable -- returned `false` and the
        // claim never released on preemption. 28 of v3's 87 farm jobs
        // (all SOW) were orphaned exactly this way: a colonist marked a
        // SOW job unreachable, got preempted into Eat/Rest/Despond, and
        // never came back to release it. This assertion is the one that
        // would have failed against that code.
        assert!(
            claim_release_should_clear(true, true),
            "a claim we hold must release on preemption even if the job is marked unreachable"
        );
        // Unchanged behavior: a reachable job we hold still releases.
        assert!(claim_release_should_clear(true, false));
        // Unchanged behavior: a claim we do NOT hold is never touched,
        // unreachable or not -- this branch was never the bug.
        assert!(!claim_release_should_clear(false, true));
        assert!(!claim_release_should_clear(false, false));
    }

    /// ★ ROW 2 AUTO-GUARD v1: the drive's own posts retract without
    /// touching a painted one. The registry IS the safety property — the
    /// exit sweep drains `auto_guard_jobs` and nothing else, so a player's
    /// standing post survives every Defend cycle.
    #[test]
    fn auto_guard_retraction_spares_painted_posts() {
        let mut board = JobBoard::default();
        let u = Uid(NonZeroU64::new(21).unwrap());
        let auto_id = board.insert_auto_guard_job(Vec3::new(5, 5, 10), u);
        // A "painted" post: same kind, inserted outside the auto path.
        let painted_id = board.next_id;
        board.next_id += 1;
        let mut painted = board.jobs[&auto_id].clone();
        painted.pos = Vec3::new(9, 9, 10);
        board.jobs.insert(painted_id, painted);

        assert_eq!(
            board.auto_guard_jobs,
            vec![auto_id],
            "only the drive's own post is registered for retraction"
        );
        // The exit sweep, exactly as the transition arm runs it.
        let retracting: Vec<JobId> = board.auto_guard_jobs.drain(..).collect();
        for id in retracting {
            board.remove_job(id);
        }
        assert!(
            !board.jobs.contains_key(&auto_id),
            "the drive's post retracts when Defend ends"
        );
        assert!(
            board.jobs.contains_key(&painted_id),
            "a player-painted post must survive the drive's exit sweep"
        );
    }

    /// ★ PROFESSIONS STAY IN THEIR LANE (Ben RULED): the trade outbids,
    /// cross-domain stays possible, defence stays communal. Both
    /// directions: the lane must actually lead, and nothing may be zeroed —
    /// a profile that FORBIDS cross-domain work recreates the starved-
    /// specialist failure this board has shipped guards against before.
    #[test]
    fn a_profession_prefers_its_lane_but_never_locks_the_door() {
        use common::bastion::{WorkPriorities, WorkType};
        let chef = WorkPriorities::in_lane(WorkType::Cook);
        assert_eq!(chef.get(WorkType::Cook), 4, "the trade leads");
        assert!(
            chef.get(WorkType::Farm) >= 1 && chef.get(WorkType::Farm) < chef.get(WorkType::Cook),
            "cross-domain work stays possible but never outbids the lane"
        );
        assert_eq!(
            chef.get(WorkType::Guard),
            3,
            "defence is everyone's business — a profession is a day job"
        );
        let farmer = WorkPriorities::in_lane(WorkType::Farm);
        assert_eq!(farmer.get(WorkType::Farm), 4);
        assert!(farmer.get(WorkType::Cook) < farmer.get(WorkType::Farm));
    }

    /// ★ THE OPEN BOARD KEEPS OFFICE HOURS (Ben: "working constantly —
    /// that's not how people work"): ordinary claims only during the Work
    /// block; evenings and nights the board is closed. Both directions —
    /// the Work block must genuinely open it, or the colony starves at its
    /// desks.
    #[test]
    fn the_open_board_keeps_office_hours() {
        assert!(
            work_claims_open(default_schedule_block(10)),
            "mid-morning: the board is open"
        );
        assert!(
            !work_claims_open(default_schedule_block(18)),
            "evening leisure: no new work claims — lounging is the job"
        );
        assert!(
            !work_claims_open(default_schedule_block(23)),
            "night: the board is closed and colonists head home"
        );
        assert!(
            !work_claims_open(default_schedule_block(2)),
            "small hours: still closed"
        );
        assert!(
            work_claims_open(default_schedule_block(8))
                && work_claims_open(default_schedule_block(15)),
            "the full 8-hour work block stays open at both ends"
        );
    }

    /// THE QUARRY's dry-wrap detector — both directions: a full wrap of
    /// dry slabs trips the survey EXACTLY at the wrap (early would range
    /// with unswept slabs left; the planted early-trip fails), and ANY
    /// rock resets (a never-reset counter would found quarries beside
    /// standing stone; the planted no-reset fails).
    #[test]
    fn quarry_survey_trips_exactly_on_a_full_dry_wrap() {
        let slabs = 9u8;
        let mut c = 0u8;
        for i in 1..=slabs {
            let (n, trip) = mine_dry_step(c, 0, slabs);
            c = n;
            assert_eq!(trip, i == slabs, "trip only at the full wrap (slab {i})");
        }
        // Any rock resets the streak.
        let (c2, trip) = mine_dry_step(c, 3, slabs);
        assert_eq!((c2, trip), (0, false), "rock seen must reset, never trip");
        // A restarted streak counts from zero again.
        let (c3, trip) = mine_dry_step(c2, 0, slabs);
        assert_eq!((c3, trip), (1, false));
    }

    /// ROW 36: the evening linger is a real multiple (the plaza-occupancy
    /// arithmetic needs ≥3× to clear one simultaneous lounger at pop 24)
    /// and the midday break stays its brisk self — the pin that catches a
    /// future retune quietly flattening evenings back to coffee breaks.
    #[test]
    fn evenings_linger_while_midday_breaks_stay_brisk() {
        // THE MEASURED CLOCK (live log: game_day 1 at tick 33,900, game_day
        // 2 at 87,900 ⇒ 54,000 ticks/day; ~30 tps ⇒ 1,800s of the `time`
        // clock per game day). Everything below is arithmetic on that.
        const SECS_PER_GAME_HOUR: f64 = 1800.0 / 24.0; // 75
        const EVENING_BLOCK_SECS: f64 = 6.0 * SECS_PER_GAME_HOUR; // 16-21 ⇒ 450
        let linger = RECREATION_BREAK_SECS * EVENING_LINGER_MULT;
        assert!(
            linger >= 2.0 * SECS_PER_GAME_HOUR,
            "under two game hours a sit is a coffee break: the plaza empties between visitors"
        );
        assert!(
            linger <= 0.75 * EVENING_BLOCK_SECS,
            "a linger longer than three quarters of the evening leaves no room for a \
             SECOND activity — the evening collapses back to one pose per colonist, \
             which is exactly what v1 did at 4x (480s > the 450s evening)"
        );
        // Occupancy still clears the row's bar: pop 24, each colonist taking
        // roughly (evening / linger) sits, each lasting `linger`.
        // ★ THE DEAD PIN (review): v1 computed
        // `24 * (EVENING/linger) * linger / EVENING`, which is 24.0 for ANY
        // constants — a witness that cannot fail, blessing whatever sizing
        // it was handed. The honest model: each colonist takes ONE lounge
        // per evening window of length `linger`, starts spread across the
        // evening, so the expected number seated at a random instant is
        // pop * linger / EVENING — a quantity that MOVES with the constant
        // it is testing.
        let expected_present = 24.0 * linger / EVENING_BLOCK_SECS;
        assert!(
            expected_present >= 6.0,
            "the row's bar is >=6 simultaneous; this sizing predicts {expected_present}"
        );
        // …and the same formula must REFUSE a sizing that empties the
        // plaza: the pre-row 120s break predicts 6.4 — barely — while half
        // of it predicts 3.2, under the bar. Proves the pin has teeth.
        assert!(
            24.0 * (RECREATION_BREAK_SECS * 0.5) / EVENING_BLOCK_SECS < 6.0,
            "the occupancy model must be able to FAIL a too-short sit"
        );
        // ★ ROW 36d — A HOLD MAY NEVER OUTLIVE ITS BLOCK. Leisure is TWO
        // windows (6-7 dawn, 16-21 evening) and the review caught the
        // linger overrunning the two-hour dawn one into the work day, on a
        // hold work cannot reclaim. Every hour of both windows is pinned.
        // v2: the clamp is EXACT — sampled every six game-minutes across
        // both leisure windows, a hold may never outlive its own block.
        // (Round 56's census caught the whole-hour version bleeding 10.6
        // seated colonists into the first WORK hour.)
        let tod_of = |h: f64| h * 3600.0;
        // ★ ROW 50 (review rank 4): PARAMETERISED OVER THE CLOCK. The old
        // pin re-asserted the same 1,800 the function hardcoded, so it
        // agreed with the defect instead of catching it — a pin that shares
        // its subject's assumption cannot test that assumption. 1,800 is
        // the default server (day_length 30); 120 is THIS PROJECT'S OWN
        // HARNESS (day_length 2.0), where the invariant was false by 15x;
        // 43,200 is a slow-day server. The invariant must hold on all of
        // them or it is not an invariant.
        for spd in [1800.0f64, 120.0, 43_200.0] {
            for step in 0..20 {
                let h = 6.0 + f64::from(step) * 0.1; // 06:00 → 07:54
                let hold =
                    leisure_hold_secs(tod_of(h), RECREATION_BREAK_SECS, EVENING_LINGER_MULT, spd);
                let remaining = (8.0 - h) * (spd / 24.0);
                assert!(
                    hold <= remaining + 1e-6,
                    "dawn {h} @ {spd}s/day: hold {hold} outlives the {remaining}s left"
                );
                assert!(hold <= RECREATION_BREAK_SECS, "dawn gets no evening linger");
            }
            for step in 0..60 {
                let h = 16.0 + f64::from(step) * 0.1; // 16:00 → 21:54
                let hold =
                    leisure_hold_secs(tod_of(h), RECREATION_BREAK_SECS, EVENING_LINGER_MULT, spd);
                let remaining = (22.0 - h) * (spd / 24.0);
                assert!(
                    hold <= remaining + 1e-6,
                    "evening {h} @ {spd}s/day: hold {hold} outlives the {remaining}s left"
                );
            }
            // Outside leisure (the midday need-break) is IDENTITY with
            // before, on every clock.
            for h in [0.0f64, 5.0, 9.5, 12.0, 15.9, 22.0, 23.5] {
                assert_eq!(
                    leisure_hold_secs(tod_of(h), RECREATION_BREAK_SECS, EVENING_LINGER_MULT, spd),
                    RECREATION_BREAK_SECS,
                    "hour {h} is not a leisure window: the break must be untouched"
                );
            }
        }
        // ★ AND THE PIN MUST BITE: on the harness clock an UNCLAMPED linger
        // genuinely overruns its block — which is exactly the bug that
        // shipped. If this ever stops holding, the clamp has become
        // untestable because the numbers no longer conflict.
        assert!(
            RECREATION_BREAK_SECS * EVENING_LINGER_MULT > 6.0 * (120.0 / 24.0),
            "on the harness clock the whole evening is 30s: the raw linger MUST overrun it"
        );
        assert!(
            leisure_hold_secs(tod_of(16.0), RECREATION_BREAK_SECS, EVENING_LINGER_MULT, 120.0)
                < RECREATION_BREAK_SECS * EVENING_LINGER_MULT,
            "the clamp must actually cut the hold on the harness clock"
        );
        assert_eq!(
            leisure_hold_secs(tod_of(16.0), RECREATION_BREAK_SECS, EVENING_LINGER_MULT, 1800.0),
            RECREATION_BREAK_SECS * EVENING_LINGER_MULT,
            "early evening still gets the full linger on the default clock"
        );
        // A day-wrapped clock reads the same as its own hour.
        assert_eq!(
            leisure_hold_secs(
                tod_of(17.0) + common::resources::DAY * 3.0,
                RECREATION_BREAK_SECS,
                EVENING_LINGER_MULT,
                1800.0
            ),
            leisure_hold_secs(tod_of(17.0), RECREATION_BREAK_SECS, EVENING_LINGER_MULT, 1800.0),
            "the clamp must read the time of DAY, not the age of the world"
        );
        // ★ ROW 50 (review rank 10): THE NIGHT WATCHMAN'S OWN CLOCK. His
        // schedule is rotated 14 hours, so read against the wall clock his
        // hold was clamped against a window he is not in.
        // `colonist_effective_tod` is the one shift, and the block it lands
        // in must AGREE with what `colonist_schedule_block` says he is doing.
        {
            let mut watch = HashSet::new();
            let w = common::uid::Uid(std::num::NonZeroU64::new(7).unwrap());
            watch.insert(w);
            for h in 0..24u32 {
                let eff = colonist_effective_tod(&watch, Some(&w), tod_of(f64::from(h)));
                assert_eq!(
                    default_schedule_block(hour_of_day(eff)),
                    colonist_schedule_block(&watch, Some(&w), h),
                    "hour {h}: the shifted clock must land in the watchman's OWN block"
                );
                assert_eq!(
                    colonist_effective_tod(&watch, None, tod_of(f64::from(h))),
                    tod_of(f64::from(h)),
                    "hour {h}: a colonist off the watch keeps the town clock exactly"
                );
            }
            // The day count must SURVIVE the shift, or the evening palette's
            // `day * 24 + hour` epoch collapses to day 0 forever and every
            // colonist does the same thing every evening for all time.
            let far = tod_of(17.0) + common::resources::DAY * 9.0;
            assert!(
                colonist_effective_tod(&watch, Some(&w), far) > common::resources::DAY * 8.0,
                "the effective clock must not be wrapped to one day"
            );
        }
    }

    /// ROW 50 (review rank 3): THE POST BELONGS TO THE COOK. The kitchen
    /// cap must bound generalists and never the person whose trade it is.
    /// Pinned as the predicate the claim loop actually evaluates, in both
    /// directions — the shipped defect passed a cap-arithmetic pin while
    /// locking the chef out, so a pin on the cap alone is not enough: it
    /// has to assert WHO.
    #[test]
    fn a_full_kitchen_still_admits_the_chef() {
        let chef = common::bastion::WorkPriorities::in_lane(common::bastion::WorkType::Cook)
            .get(common::bastion::WorkType::Cook);
        let hauler = common::bastion::WorkPriorities::in_lane(common::bastion::WorkType::Haul)
            .get(common::bastion::WorkType::Cook);
        let generalist =
            common::bastion::WorkPriorities::default().get(common::bastion::WorkType::Cook);
        assert!(chef >= COOK_LANE_BAR, "in_lane(Cook) must clear the lane bar");
        assert!(
            hauler < COOK_LANE_BAR && generalist < COOK_LANE_BAR,
            "a hauler and a default colonist must both be BELOW it, or the cap bounds nobody"
        );
        // ★ PIN-AUDIT REWRITE (2026-08-29): this loop used to call a LOCAL
        // `admits` closure that duplicated the production logic, so the
        // production guard had no coverage anywhere in the crate — moving
        // the cap back above the priority read (ROW 43's shipped behaviour,
        // which refused the chef his own stove) left the suite green. It now
        // calls the REAL `kitchen_admits`, with the cap from the REAL
        // `kitchen_crew_cap`.
        for roster in [8usize, 12, 24, 60, 120] {
            let cap = kitchen_crew_cap(roster);
            assert!(
                kitchen_admits(cap - 1, cap, hauler),
                "roster {roster}: under cap a generalist may still cook"
            );
            assert!(
                !kitchen_admits(cap, cap, hauler),
                "roster {roster}: at cap a generalist must be refused"
            );
            assert!(
                !kitchen_admits(cap + 3, cap, generalist),
                "roster {roster}: over cap too"
            );
            // …and the chef never is. THIS is the assertion the shipped
            // version would have failed, and the one the dead closure faked.
            assert!(
                kitchen_admits(cap, cap, chef),
                "roster {roster}: at cap the CHEF must still get a stove"
            );
            assert!(
                kitchen_admits(cap + 9, cap, chef),
                "roster {roster}: even a kitchen full of amateurs"
            );
        }
    }
    /// ★ PIN-AUDIT REWRITE (2026-08-29). The previous version of this test
    /// was DEAD: it contained zero production symbols, hand-wrote its own
    /// `churning: [bool; 6]` and its own `budget = 3` (the real cap was a
    /// function-local const no test could name), and modelled both orderings
    /// as inline loops. Its closing assertion const-folded to `3 > 1`. It
    /// reported safety over the ROW 50 rank-1 fix while guarding nothing.
    ///
    /// It now calls the REAL `farm_cell_free` and the REAL
    /// `FARM_OPEN_JOBS_PER_PLOT`, so deleting the churn term from the
    /// predicate fails this test.
    #[test]
    fn a_rested_farm_cell_costs_the_plot_nothing() {
        use std::collections::HashSet;
        let occupied: HashSet<Vec3<i32>> = HashSet::new();
        // Two cells the work tick keeps calling moot, then four good ones.
        let cells: Vec<Vec3<i32>> = (0..6).map(|i| Vec3::new(i, 0, 60)).collect();
        let churning: HashSet<(i32, i32, i32)> =
            [(0, 0, 60), (1, 0, 60)].into_iter().collect();

        // THE PROPERTY: the plot's budget is spent only on cells that can
        // actually produce work. A rested cell must cost the plot nothing.
        let minted: Vec<Vec3<i32>> = cells
            .iter()
            .copied()
            .filter(|p| farm_cell_free(&occupied, &churning, *p))
            .take(FARM_OPEN_JOBS_PER_PLOT)
            .collect();
        assert_eq!(
            minted.len(),
            4,
            "four free cells remain; the two rested ones must not be minted"
        );
        assert!(
            minted
                .iter()
                .all(|p| !churning.contains(&(p.x, p.y, p.z))),
            "a rested cell was charged to the plot budget — the shipped \
             debit-then-filter order has come back"
        );

        // And the predicate refuses for BOTH reasons, independently — pin the
        // threshold against each degenerate setting.
        let occ: HashSet<Vec3<i32>> = [Vec3::new(9, 9, 60)].into_iter().collect();
        let none: HashSet<(i32, i32, i32)> = HashSet::new();
        assert!(!farm_cell_free(&occ, &none, Vec3::new(9, 9, 60)), "occupied must refuse");
        assert!(farm_cell_free(&occ, &none, Vec3::new(8, 9, 60)), "a free cell must pass");
        assert!(
            !farm_cell_free(&HashSet::new(), &churning, Vec3::new(0, 0, 60)),
            "rested must refuse even when nothing is occupied"
        );
        // The cap is a real, nameable quantity, not a number the test invented.
        assert!(
            FARM_OPEN_JOBS_PER_PLOT > 0 && FARM_OPEN_JOBS_PER_PLOT <= 64,
            "the per-plot cap must be a sane bound; 0 would stop the farm dead"
        );
    }
    /// ★ PIN-AUDIT REWRITE (2026-08-29). The previous version hand-wrote the
    /// same `dz` span it was meant to be checking, so reverting the
    /// production release to a single cell, narrowing it, or widening it
    /// left the test green. It now asserts the KEYS the production function
    /// actually returns.
    ///
    /// ROW 50 rank-5: a till stands at gpos while the sow it cures lives at
    /// cpos = gpos + z, so a release keyed to the acting cell alone could
    /// never free the cell the till had just fixed — and ROW 40 advertised
    /// exactly that cure.
    #[test]
    fn tilling_a_column_releases_the_sow_cell_above_it() {
        let gpos = Vec3::new(4, 9, 60);
        let cpos = gpos + Vec3::unit_z();
        let keys = farm_moot_release_keys(gpos);

        // The cell above (the sow) MUST be released by a till acting below.
        assert!(
            keys.contains(&(cpos.x, cpos.y, cpos.z)),
            "a till at gpos must release the sow cell above it"
        );
        // And the acting cell itself, and the cell below (harvest releasing
        // the till it stands on).
        assert!(keys.contains(&(gpos.x, gpos.y, gpos.z)), "the acting cell");
        assert!(keys.contains(&(gpos.x, gpos.y, gpos.z - 1)), "the cell below");
        // Exactly the column — not the neighbourhood. A release that is too
        // WIDE would clear cells nothing cured, hiding real churn.
        assert_eq!(keys.len(), 3, "the release must span the column, no more");
        assert!(
            keys.iter().all(|k| k.0 == gpos.x && k.1 == gpos.y),
            "the release must never leave the column"
        );

        // End to end against the real churn predicate: rest the sow cell,
        // act a till below it, and the sow must be workable again.
        let mut moot: HashMap<(i32, i32, i32), u32> = HashMap::new();
        for _ in 0..FARM_MOOT_LIMIT {
            *moot.entry((cpos.x, cpos.y, cpos.z)).or_insert(0) += 1;
        }
        assert!(farm_cell_is_churning(moot.get(&(cpos.x, cpos.y, cpos.z))));
        for k in farm_moot_release_keys(gpos) {
            moot.remove(&k);
        }
        assert!(
            !farm_cell_is_churning(moot.get(&(cpos.x, cpos.y, cpos.z))),
            "a till that cures the column must return the sow cell to work"
        );
    }

    /// ROW 50 (review rank 2): EVERY profession maps to the lane the
    /// founding path gives it, from ONE map. The drifted copy is what
    /// froze the militia at its founding size while the town grew.
    #[test]
    fn a_settler_hunter_joins_the_militia() {
        use common::bastion::{WorkPriorities, WorkType};
        use common::rtsim::Profession;
        for p in [Profession::Hunter, Profession::Guard] {
            assert_eq!(
                WorkPriorities::work_for_profession(p),
                Some(WorkType::Guard),
                "{p:?} must be militia — the muster, the alarm exemption and the night watch \
                 all test guard priority, and nothing ever rewrites priorities later"
            );
        }
        // ★ THE CONSEQUENCE, not just the mapping: the lane profile a
        // settler ends up with must actually clear the bar those three
        // predicates use. `in_lane` leaves guard at 3 for every OTHER lane,
        // which is why the mis-mapping was silent.
        let militia = WorkPriorities::in_lane(WorkType::Guard);
        assert!(
            militia.get(WorkType::Guard) >= 4,
            "an in-lane guard must clear the muster's own threshold"
        );
        for other in [WorkType::Farm, WorkType::Cook, WorkType::Build, WorkType::Haul] {
            assert!(
                WorkPriorities::in_lane(other).get(WorkType::Guard) < 4,
                "{other:?} must NOT be militia, or the mapping stops mattering"
            );
        }
    }

    /// ROW 50 (CHILDREN): the birth gate, both directions — every refusal
    /// reachable and named, and it fires only when a family has room in a
    /// town that has room.
    #[test]
    fn a_town_makes_its_own_people_only_when_it_can_hold_them() {
        use common::bastion::ColonyDrive as D;
        // ROW 53 shape: (enabled, drive, adults, adults_required, beds,
        // family_size, couples, roster, target, today, last).
        let ok = birth_verdict(true, D::Expand, 2, 1, 4, 2, 0, 10, 20, 5, Some(4));
        assert!(ok.fired, "two adults, beds spare, town under target: a child");
        for (v, why) in [
            (birth_verdict(false, D::Expand, 2, 1, 4, 2, 0, 10, 20, 5, Some(4)), "disabled"),
            (birth_verdict(true, D::Expand, 2, 1, 4, 2, 0, 10, 20, 5, Some(5)), "same_day"),
            (
                birth_verdict(true, D::Sustain, 2, 1, 4, 2, 0, 10, 20, 5, Some(4)),
                "drive_not_expand",
            ),
            (birth_verdict(true, D::Expand, 0, 1, 4, 1, 0, 10, 20, 5, Some(4)), "no_family"),
            (birth_verdict(true, D::Expand, 2, 1, 2, 2, 0, 10, 20, 5, Some(4)), "house_full"),
            (
                birth_verdict(true, D::Expand, 2, 1, 4, 2, 0, 20, 20, 5, Some(4)),
                "no_room_in_town",
            ),
        ] {
            assert!(!v.fired, "{why}: must refuse");
            assert_eq!(v.deciding, why, "the refusal must NAME itself");
        }
        // ★ THE HOUSING EQUATION BINDS BIRTHS TOO, so growth self-limits
        // with no second governor: at target, no arithmetic of family size
        // can produce a child.
        for adults in 2..=6u32 {
            for beds in 1..=6u32 {
                assert!(
                    !birth_verdict(
                        true, D::Expand, adults, 1, beds, adults, 0, 20, 20, 5, None
                    )
                    .fired,
                    "a full town must not grow from the inside either"
                );
            }
        }
        // ★ THE GATE MUST BE REACHABLE IN THE TOWN THAT EXISTS. The first
        // cut required two adults under one roof, and both live worlds read
        // shared=0 on every sample — Ben's "ONE COLONIST PER HOUSE" ruling
        // is actively enforced by the move-out pass, so a two-adult gate
        // was unreachable BY CONSTRUCTION and would have shipped dead,
        // deciding no_family forever while looking like a rule correctly
        // declining. This asserts the shape the town actually has: a
        // single-occupant household with spare beds CAN bear a child.
        // (ROW 53 keeps it as the COURTSHIP-OFF shape — see
        // `adults_required_for_birth`.)
        for beds in 2..=6u32 {
            assert!(
                birth_verdict(true, D::Expand, 1, 1, beds, 1, 0, 3, 20, 5, None).fired,
                "beds {beds}: a one-adult household with room must be able to bear a \
                 child, or the gate is unreachable in a town that keeps one colonist \
                 per house"
            );
        }
        // …and a household with NO adult left (the parent died, only
        // children remain) still refuses — the refusal has to keep a real
        // case or the term stops meaning anything.
        for beds in 1..=6u32 {
            assert!(!birth_verdict(true, D::Expand, 0, 1, beds, 1, 0, 3, 20, 5, None).fired);
        }
        // A one-bed hut is full with its single occupant: capacity binds
        // before family does.
        assert_eq!(
            birth_verdict(true, D::Expand, 1, 1, 1, 1, 0, 3, 20, 5, None).deciding,
            "house_full"
        );
    }

    /// ★★ ROW 53: THE GATE THAT WOULD HAVE SHIPPED DEAD FOR THE SECOND
    /// TIME. Every adopted house has exactly TWO beds (measured:
    /// `adopted_beds=2` on all 80 houses of one logged town), so
    /// `household_capacity(2) == 2` and a cohabiting couple ALREADY FILLS
    /// IT. Restoring the two-adult birth gate without the cot would refuse
    /// `house_full` forever — the same silence as the `no_family` defect,
    /// from a different cause, and just as invisible.
    ///
    /// This is the pin that would have caught it, written against the
    /// measured 2-bed house and nothing else.
    #[test]
    fn a_two_bed_house_holds_a_couple_and_their_first_child() {
        use common::bastion::ColonyDrive as D;
        const BEDS: u32 = 2; // the measured adopted house
        // The identity first: no couples ⇒ room IS capacity, everywhere.
        for beds in 0..=9u32 {
            assert_eq!(
                household_room(beds, 0),
                household_capacity(beds),
                "beds {beds}: with no couple the cot must not exist"
            );
        }
        // WITHOUT the cot — capacity alone — a couple fills the house and
        // the gate is unreachable. Stated as the counterfactual so the pin
        // fails loudly if `household_room` is ever reduced to capacity.
        assert!(
            2 >= household_capacity(BEDS),
            "the premise: a couple already fills a 2-bed house by capacity"
        );
        // WITH the cot the couple can bear their first child…
        let couple = birth_verdict(true, D::Expand, 2, 2, BEDS, 2, 1, 10, 20, 5, None);
        assert!(couple.fired, "a couple in a 2-bed house must be able to bear a child");
        // …and exactly one: with the infant the family is 3 of 3.
        let with_infant = birth_verdict(true, D::Expand, 2, 2, BEDS, 3, 1, 10, 20, 5, None);
        assert!(!with_infant.fired);
        assert_eq!(with_infant.deciding, "house_full");
        // The bedless infant MUST be counted, or the same house bears a
        // second child against the bed the first is still waiting for.
        let owners_only = birth_verdict(true, D::Expand, 2, 2, BEDS, 2, 1, 10, 20, 5, None);
        assert!(
            owners_only.fired && !with_infant.fired,
            "family_size must count bedless children, not just bed owners"
        );
        // And a SINGLE adult in a 2-bed house refuses `no_family` once
        // courtship is on — which is the whole point of the tightening.
        assert_eq!(
            birth_verdict(true, D::Expand, 1, 2, BEDS, 1, 0, 10, 20, 5, None).deciding,
            "no_family"
        );
        // ★★ AND THE BIRTH LADDER'S ORDER, WHICH THE SHIPPED ROW 50 PIN
        // CANNOT SEE. Every case in that pin violates exactly ONE gate, so
        // reordering the whole ladder leaves all six answers unchanged —
        // the same blind spot a deliberate inversion found in the courtship
        // pin. These inputs violate several arms at once and assert the
        // EARLIEST one answers.
        for (v, why) in [
            (
                birth_verdict(false, D::Sustain, 0, 2, 1, 9, 0, 99, 1, 5, Some(5)),
                "disabled",
            ),
            (
                birth_verdict(true, D::Sustain, 0, 2, 1, 9, 0, 99, 1, 5, Some(5)),
                "same_day",
            ),
            (
                birth_verdict(true, D::Sustain, 0, 2, 1, 9, 0, 99, 1, 5, None),
                "drive_not_expand",
            ),
            (birth_verdict(true, D::Expand, 0, 2, 1, 9, 0, 99, 1, 5, None), "no_family"),
            (birth_verdict(true, D::Expand, 2, 2, 1, 9, 0, 99, 1, 5, None), "house_full"),
            (
                birth_verdict(true, D::Expand, 2, 2, 4, 1, 0, 99, 1, 5, None),
                "no_room_in_town",
            ),
        ] {
            assert!(!v.fired);
            assert_eq!(
                v.deciding, why,
                "the birth ladder must answer with its EARLIEST failing gate"
            );
        }
        // The requirement itself is a function of courtship, so the
        // fallback reverts it exactly.
        assert_eq!(adults_required_for_birth(true), 2);
        assert_eq!(adults_required_for_birth(false), 1);
        assert!(
            birth_verdict(
                true,
                D::Expand,
                1,
                adults_required_for_birth(false),
                BEDS,
                1,
                0,
                10,
                20,
                5,
                None
            )
            .fired,
            "BASTION_NO_COURTSHIP must restore the one-adult gate exactly"
        );
    }

    /// ROW 53: the courtship gate, both directions — every refusal
    /// reachable and NAMED, in the order it is written, and the fire arm
    /// reachable from the shape a real town has.
    #[test]
    fn the_town_pairs_people_and_every_refusal_names_itself() {
        let ok = courtship_verdict(true, 5, Some(4), 6, 12, 3, true);
        assert!(ok.fired);
        for (v, why) in [
            (courtship_verdict(false, 5, Some(4), 6, 12, 3, true), "disabled"),
            (courtship_verdict(true, 5, Some(5), 6, 12, 3, true), "same_day"),
            (courtship_verdict(true, 5, Some(4), 1, 0, 0, true), "no_candidates"),
            (courtship_verdict(true, 5, Some(4), 6, 0, 0, true), "all_kin"),
            (courtship_verdict(true, 5, Some(4), 6, 12, 0, true), "no_mutual_interest"),
            (courtship_verdict(true, 5, Some(4), 6, 12, 3, false), "no_home"),
        ] {
            assert!(!v.fired, "{why}: must refuse");
            assert_eq!(v.deciding, why, "the refusal must NAME itself");
        }
        // Day 0 is a real day, not "already fired" — the same corner the
        // immigration latch has a pin for.
        assert!(courtship_verdict(true, 0, None, 2, 1, 1, true).fired);
        // ★★ AND THE ORDER IS THE POINT — PINNED WHERE IT CAN ACTUALLY BE
        // SEEN. This assertion exists because the first version of this pin
        // COULD NOT SEE arm order at all: every case above violates exactly
        // ONE gate, so reordering the whole ladder left all six answers
        // unchanged and the pin stayed green through a deliberate
        // inversion. A refusal ladder is only pinned by inputs that violate
        // SEVERAL arms at once and assert the EARLIER one wins.
        //
        // (The shipped ROW 50 birth pin has the same blind spot; see the
        // matching block in `a_two_bed_house_holds_a_couple_and_their_first_child`.)
        for (v, why) in [
            // Everything is wrong at once: the earliest arm must speak.
            (courtship_verdict(false, 5, Some(5), 0, 0, 0, false), "disabled"),
            (courtship_verdict(true, 5, Some(5), 0, 0, 0, false), "same_day"),
            (courtship_verdict(true, 5, None, 0, 0, 0, false), "no_candidates"),
            (courtship_verdict(true, 5, None, 9, 0, 0, false), "all_kin"),
            (courtship_verdict(true, 5, None, 9, 9, 0, false), "no_mutual_interest"),
            (courtship_verdict(true, 5, None, 9, 9, 9, false), "no_home"),
        ] {
            assert!(!v.fired);
            assert_eq!(
                v.deciding, why,
                "the refusal ladder must answer with its EARLIEST failing gate"
            );
        }
        // ★ NOT GATED ON ColonyDrive: there is no drive parameter to pass,
        // which is the strongest form this assertion can take. See the ROW
        // 53 header block for why adding one would be a regression.
    }

    /// ★★ ROW 53: AFFINITY IS SYMMETRIC AS A THEOREM, NOT AS A DISCIPLINE.
    /// The canonicalisation lives INSIDE `pair_affinity`, so swapping the
    /// arguments evaluates the same expression on the same operands. Swept
    /// over a grid rather than sampled, because an asymmetric score would
    /// make the matching depend on enumeration order — the exact failure
    /// the uid sort exists to prevent, arriving by another door.
    #[test]
    fn affinity_is_symmetric_and_the_evidence_dominates() {
        let m1 = [true, false, false, true, true, false, false, false, true, false];
        let m2 = [false, true, false, true, true, false, true, false, false, true];
        for (ua, ub) in [(3u64, 9u64), (9, 3), (1, 1_000_000), (7, 8)] {
            for (sab, sba) in [(0.0f32, 0.0f32), (0.4, 0.1), (0.1, 0.4), (-0.5, 0.9)] {
                for day in [0i64, 1, 77] {
                    let a = pair_affinity(
                        ua,
                        ub,
                        sab,
                        sba,
                        m1,
                        m2,
                        Vec3::new(10, 20, 30),
                        Vec3::new(14, 25, 30),
                        day,
                    );
                    let b = pair_affinity(
                        ub,
                        ua,
                        sba,
                        sab,
                        m2,
                        m1,
                        Vec3::new(14, 25, 30),
                        Vec3::new(10, 20, 30),
                        day,
                    );
                    assert_eq!(
                        a.to_bits(),
                        b.to_bits(),
                        "pair_affinity({ua},{ub}) != pair_affinity({ub},{ua}) — bitwise"
                    );
                }
            }
        }
        // ★ ONE-SIDED INFATUATION MUST NOT MARRY ANYBODY: `min`, not `sum`.
        // A sum would rank the lopsided pair ABOVE the mutual one here.
        let neutral = [false; PERSONALITY_MASK];
        let bed = Vec3::new(0, 0, 0);
        let mutual = pair_affinity(1, 2, 0.25, 0.25, neutral, neutral, bed, bed, 0);
        let lopsided = pair_affinity(1, 2, 0.9, 0.0, neutral, neutral, bed, bed, 0);
        assert!(
            mutual > lopsided,
            "a sum would have preferred the one-sided pair: {mutual} vs {lopsided}"
        );
        // ★ THE SPARK MAY SEPARATE, NEVER DECIDE. Bounded an order of
        // magnitude below the evidence it sits beside.
        for day in 0..500i64 {
            let s = pair_spark(3, 11, day);
            assert!(
                (0.0..=COURTSHIP_SPARK).contains(&s),
                "day {day}: spark {s} escaped its bound"
            );
        }
        assert!(
            COURTSHIP_SPARK * 4.0 < COURTSHIP_SENTIMENT_BAR,
            "the spark must not be able to carry a pair over the evidence bar"
        );
        assert_eq!(pair_spark(3, 11, 7), pair_spark(3, 11, 7), "deterministic");
        let across: std::collections::HashSet<u32> =
            (0..40i64).map(|d| pair_spark(3, 11, d).to_bits()).collect();
        assert!(across.len() > 20, "the spark must actually re-roll by day");
        // ROW 53: proximity has the sign it claims — you court whom you
        // live near.
        let near = pair_affinity(
            1, 2, 0.3, 0.3, neutral, neutral, Vec3::new(0, 0, 0), Vec3::new(2, 0, 0), 4,
        );
        let far = pair_affinity(
            1, 2, 0.3, 0.3, neutral, neutral, Vec3::new(0, 0, 0), Vec3::new(90, 0, 0), 4,
        );
        assert!(near > far, "the far neighbour must not outrank the near one");
        // Personality compatibility is symmetric and signed the right way.
        assert_eq!(personality_compat(m1, m2), personality_compat(m2, m1));
        let same = [true, false, true, false, true, false, true, false, true, false];
        let opp = [false, true, false, true, false, true, false, true, false, true];
        assert_eq!(personality_compat(same, same), PERSONALITY_AXES as i32);
        assert_eq!(personality_compat(same, opp), -(PERSONALITY_AXES as i32));
        assert_eq!(personality_compat([false; PERSONALITY_MASK], same), 0);
    }

    /// ★ ROW 53: THE MATCH IS ORDER-INDEPENDENT OVER THE INPUT SET.
    /// `pair_sort_key` is a TOTAL order — score first, then the canonical
    /// uid pair, which is unique — so the greedy match below it cannot
    /// depend on the order specs handed the candidates over.
    #[test]
    fn the_greedy_match_is_a_function_of_the_set_not_of_the_order() {
        // A hand-built pair table: (lo, hi, score).
        //
        // ★ THE TIE HAS TO MATTER, and the first version of this table made
        // sure it did not: its two tied pairs both wanted the same
        // already-taken partner, so greedy skipped one of them whatever the
        // order was, and DELETING the uid tiebreak entirely left this pin
        // green. `sort_by_key` is STABLE, so with no tiebreak the winner is
        // whichever tied pair the caller happened to hand over first — the
        // exact iteration-order dependency the key exists to kill.
        //
        // (5,6) and (5,7) are that tie: same score, both fully available,
        // and they compete for colonist 5.
        let pairs = [
            (1u64, 2u64, 0.31f32),
            (1, 3, 0.42),
            (2, 3, 0.42),
            (3, 4, 0.20),
            (2, 4, 0.55),
            (1, 4, 0.11),
            (5, 6, 0.50),
            (5, 7, 0.50),
        ];
        let matched = |order: &[usize]| -> Vec<(u64, u64)> {
            let mut keyed: Vec<((i64, u64, u64), u64, u64)> = order
                .iter()
                .map(|i| {
                    let (lo, hi, s) = pairs[*i];
                    (pair_sort_key(s, lo, hi), lo, hi)
                })
                .collect();
            keyed.sort_by_key(|(k, ..)| *k);
            let mut taken: std::collections::HashSet<u64> = Default::default();
            let mut out = Vec::new();
            for (_, lo, hi) in keyed {
                if taken.contains(&lo) || taken.contains(&hi) {
                    continue;
                }
                taken.insert(lo);
                taken.insert(hi);
                out.push((lo, hi));
            }
            out
        };
        let forward: Vec<usize> = (0..pairs.len()).collect();
        let backward: Vec<usize> = (0..pairs.len()).rev().collect();
        let shuffled = [3usize, 0, 7, 5, 2, 6, 4, 1];
        let a = matched(&forward);
        assert_eq!(a, matched(&backward), "reversing the input changed the match");
        assert_eq!(a, matched(&shuffled), "permuting the input changed the match");
        assert_eq!(a[0], (2, 4), "the best pair must be taken first");
        // ★ THE LIVE TIE: (5,6) and (5,7) score identically and both are
        // free, so ONLY the uid tiebreak can choose. (5,6) precedes (5,7).
        assert!(
            a.contains(&(5, 6)) && !a.contains(&(5, 7)),
            "the tie must break on the canonical uid pair, not on input order: {a:?}"
        );
        assert!(a.contains(&(1, 3)), "and the lower tied pair wins throughout: {a:?}");
        // A NaN score must not silently permute anything: it sorts LAST.
        let nan = pair_sort_key(f32::NAN, 1, 2);
        let real = pair_sort_key(-1.0, 1, 2);
        assert!(nan > real, "a NaN score must rank below every real one, not anywhere");
    }

    /// ROW 53: kinship, both directions and both parents. `parent_b` is
    /// exactly what makes the half-sibling case detectable at all — with
    /// only one recorded parent the third assertion below cannot be made.
    #[test]
    fn the_town_does_not_marry_its_own_siblings() {
        use slotmap::KeyData;
        let npc = |n: u64| -> common::rtsim::NpcId {
            KeyData::from_ffi((1u64 << 32) | n).into()
        };
        let (ann, bob, cal, dot, eve) = (npc(1), npc(2), npc(3), npc(4), npc(5));
        let none = [None, None];
        // Strangers may marry.
        assert!(!is_kin(ann, none, bob, none));
        // Parent and child, either way round, through EITHER field.
        assert!(is_kin(ann, none, cal, [Some(ann), None]));
        assert!(is_kin(cal, [Some(ann), None], ann, none));
        assert!(is_kin(ann, none, cal, [None, Some(ann)]));
        assert!(is_kin(cal, [None, Some(ann)], ann, none));
        // Full siblings.
        assert!(is_kin(cal, [Some(ann), Some(bob)], dot, [Some(ann), Some(bob)]));
        // ★ HALF-SIBLINGS THROUGH THE SECOND PARENT — invisible without
        // `parent_b`, and this is the assertion that proves it: the two
        // share only `bob`, who is recorded in the second slot for one of
        // them.
        assert!(is_kin(cal, [Some(ann), Some(bob)], dot, [Some(eve), Some(bob)]));
        assert!(
            !is_kin(cal, [Some(ann), None], dot, [Some(eve), None]),
            "and unrelated children of different parents are NOT kin"
        );
        // Symmetric everywhere.
        for (a, ap, b, bp) in [
            (ann, none, bob, none),
            (cal, [Some(ann), Some(bob)], dot, [Some(eve), Some(bob)]),
            (ann, none, cal, [Some(ann), None]),
        ] {
            assert_eq!(is_kin(a, ap, b, bp), is_kin(b, bp, a, ap), "kinship must be symmetric");
        }
        // Nobody marries themself.
        assert!(is_kin(ann, none, ann, none));
    }

    /// ★★ ROW 53: THE NUMBER THAT WOULD HAVE FALSELY REGRESSED. `shared`
    /// conflates a FAMILY with the founding claim race cramming strangers
    /// into one house, so the standing `shared == 0` criterion would have
    /// read the first couple moving in as a defect. The split must be
    /// NUMERICALLY IDENTICAL before courtship exists, which is what makes
    /// moving the criterion to `crowded == 0` safe in the same commit.
    #[test]
    fn a_family_is_not_a_crowd() {
        let m = |uid: u64, partner: Option<u64>, parents: [Option<u64>; 2]| KinMember {
            uid,
            partner,
            parents,
        };
        // BEFORE courtship: no partners, no recorded parents. Every shared
        // house is a CROWD, so families == 0 and crowded == shared.
        let strangers = [m(1, None, [None, None]), m(2, None, [None, None])];
        assert!(!household_is_family(&strangers), "two strangers are not a family");
        assert_eq!(household_couples(&strangers), 0);
        // A couple.
        let couple = [m(1, Some(2), [None, None]), m(2, Some(1), [None, None])];
        assert!(household_is_family(&couple));
        assert_eq!(household_couples(&couple), 1, "counted ONCE per pair, not per person");
        // A couple and their grown child who still owns a bed at home.
        let with_child = [
            m(1, Some(2), [None, None]),
            m(2, Some(1), [None, None]),
            m(9, None, [Some(1), Some(2)]),
        ];
        assert!(household_is_family(&with_child));
        assert_eq!(household_couples(&with_child), 1);
        // A single parent and child is a family too (the ROW 50 shape).
        let single_parent = [m(1, None, [None, None]), m(9, None, [Some(1), None])];
        assert!(household_is_family(&single_parent));
        assert_eq!(household_couples(&single_parent), 0);
        // A couple with a LODGER is not a family — the lodger is the crowd.
        let lodger = [
            m(1, Some(2), [None, None]),
            m(2, Some(1), [None, None]),
            m(7, None, [None, None]),
        ];
        assert!(!household_is_family(&lodger));
        // Degenerate shapes.
        assert!(household_is_family(&[]), "an empty house is not a crowd");
        assert!(household_is_family(&[m(1, None, [None, None])]), "nor a single occupant");
        // A partner who does NOT live here does not make this a family, and
        // does not earn a cot.
        let half = [m(1, Some(99), [None, None]), m(2, None, [None, None])];
        assert!(!household_is_family(&half));
        assert_eq!(household_couples(&half), 0, "an absent spouse earns no cot");

        // ★★ AND THE MOVE-OUT EXEMPTION, WHICH MUST SHIP IN THE SAME COMMIT
        // AS THE UNION. Without it the pass evicts the junior partner within
        // two sweeps and the town produces couples that dissolve daily —
        // while every count in the census reads exactly as it does today.
        let here = [1u64, 2, 9];
        assert!(
            move_out_exempt_partner(&m(2, Some(1), [None, None]), &here),
            "a spouse living here must NOT be moved out"
        );
        assert!(
            !move_out_exempt_partner(&m(2, None, [None, None]), &here),
            "and an unattached sharer still must be — the pass keeps its job"
        );
        assert!(
            !move_out_exempt_partner(&m(2, Some(77), [None, None]), &here),
            "a spouse living SOMEWHERE ELSE does not exempt you from moving out"
        );
        assert!(
            !move_out_exempt_partner(&m(9, None, [Some(1), Some(2)]), &here),
            "a grown child is NOT exempt through this door — childhood's own \
             exemption ends on its own, and that is what gives them a house"
        );
    }

    /// ROW 53: the courtship clock is the CHILDHOOD clock — persistent
    /// (`Data.tick`), derived denominator, never the wall and never
    /// `born_day`.
    #[test]
    fn a_courtship_is_measured_in_game_days_on_a_persistent_clock() {
        let tpgd = ticks_per_game_day(1.0 / 30.0, 48.0);
        assert!((tpgd - 54_000.0).abs() < 1.0, "the measured default: {tpgd}");
        let began = 1_000_000u64;
        let at = |d: f64| began + (d * tpgd) as u64;
        assert!(!courtship_is_ripe(at(0.0), began, tpgd));
        assert!(
            !courtship_is_ripe(at(COURTSHIP_DAYS as f64 - 0.05), began, tpgd),
            "a courtship must not seal a day early"
        );
        assert!(courtship_is_ripe(at(COURTSHIP_DAYS as f64), began, tpgd));
        assert!(courtship_is_ripe(at(COURTSHIP_DAYS as f64 + 10.0), began, tpgd));
        // A harness running a different day_length must still see
        // COURTSHIP_DAYS of GAME time, not of ticks.
        let harness = ticks_per_game_day(1.0 / 30.0, 720.0);
        assert!(harness > 0.0 && harness < tpgd);
        assert!(courtship_is_ripe(
            (COURTSHIP_DAYS as f64 * harness) as u64,
            0,
            harness
        ));
        // A rolled-back save must not seal every courtship at once.
        assert!(!courtship_is_ripe(5, 1_000, tpgd), "a backwards clock must refuse");
        // A degenerate denominator must not ripen everybody instantly.
        assert!(!courtship_is_ripe(1, 0, 0.0));
        assert!(!courtship_is_ripe(1, 0, f64::NAN));
        assert!(
            (1..=30).contains(&COURTSHIP_DAYS),
            "a courtship nobody can watch end is a courtship that does not exist"
        );
    }

    /// ROW 53: where a junior partner would sleep. Deterministic against a
    /// HashMap source, house-scoped, and nearest-first.
    #[test]
    fn cohabitation_picks_a_free_bed_in_the_right_house() {
        let mut beds: HashMap<Vec3<i32>, common::bastion::BedSlot> = HashMap::new();
        let mut bed_house: HashMap<Vec3<i32>, usize> = HashMap::new();
        let uid = |n: u64| common::uid::Uid(std::num::NonZeroU64::new(n).expect("nonzero"));
        // House 0: two beds, one owned. House 1: one bed, owned.
        let (a0, a1) = (Vec3::new(0, 0, 40), Vec3::new(3, 0, 40));
        let b0 = Vec3::new(60, 0, 40);
        for (p, owner, house) in [
            (a0, Some(uid(1)), 0usize),
            (a1, None, 0),
            (b0, Some(uid(2)), 1),
        ] {
            beds.insert(p, common::bastion::BedSlot { kind: common::bastion::BedKind::Frame, owner, occupant: None });
            bed_house.insert(p, house);
        }
        assert_eq!(
            free_bed_in_house(&beds, &bed_house, a0, b0),
            Some(a1),
            "the junior takes the free bed in the senior's own house"
        );
        assert_eq!(
            free_bed_in_house(&beds, &bed_house, b0, a0),
            None,
            "a full house offers nothing — this is the `no_home` case"
        );
        assert_eq!(
            free_bed_in_house(&beds, &bed_house, Vec3::new(999, 999, 999), a0),
            None,
            "a bed outside every derived house belongs to no household"
        );
        // Determinism against the HashMap: two equally free beds resolve to
        // the nearest, and equidistant ones to the (x,y,z)-lowest.
        let a2 = Vec3::new(-3, 0, 40);
        beds.insert(a2, common::bastion::BedSlot { kind: common::bastion::BedKind::Frame, owner: None, occupant: None });
        bed_house.insert(a2, 0);
        let picked = free_bed_in_house(&beds, &bed_house, a0, b0);
        assert_eq!(picked, Some(a1), "nearest to the mover's own bed wins");
        for _ in 0..20 {
            assert_eq!(
                free_bed_in_house(&beds, &bed_house, a0, b0),
                picked,
                "the pick must not depend on HashMap iteration order"
            );
        }
    }

    /// ROW 50 (CHILDREN): childhood is an empty work profile, and coming of
    /// age is heritage-first. Both halves pinned — a childhood with no end
    /// is a permanent dependent, and an end with no inheritance is not the
    /// mechanism Ben chartered.
    #[test]
    fn a_child_holds_no_trade_until_it_comes_of_age() {
        use common::bastion::{WorkPriorities, WorkType};
        let child = WorkPriorities::childhood();
        assert!(child.is_all_zero(), "childhood must refuse EVERY lane");
        for w in [
            WorkType::Farm,
            WorkType::Cook,
            WorkType::Build,
            WorkType::Haul,
            WorkType::Mine,
            WorkType::Chop,
            WorkType::Guard,
        ] {
            assert_eq!(child.get(w), 0, "{w:?}: the claim loop's gate is priority == 0");
            assert!(
                !WorkPriorities::in_lane(w).is_all_zero(),
                "{w:?}: an in-lane adult must never test as a child"
            );
        }
        assert!(
            !WorkPriorities::default().is_all_zero(),
            "the DEFAULT colonist must never test as a child — every founder would be one"
        );
        assert_eq!(
            coming_of_age_trade(Some(WorkType::Build), WorkType::Farm),
            WorkType::Build,
            "the smith's child inclines to the forge"
        );
        assert_eq!(
            coming_of_age_trade(None, WorkType::Mine),
            WorkType::Mine,
            "with no parent lane to inherit, the town's scarcest lane takes them"
        );
        // ★ PIN-AUDIT REWRITE (2026-08-29): this block used to define
        // `grown_on = born + CHILDHOOD_DAYS` and then assert
        // `grown_on - born >= CHILDHOOD_DAYS` — an i64 identity for every
        // value, with `born` cancelling out. It could not see
        // CHILDHOOD_DAYS change, could not see `>=` become `>`, and could
        // not see the rule deleted. It now calls the REAL `has_come_of_age`.
        //
        // PIN THE THRESHOLD AGAINST BOTH DEGENERATE SETTINGS: a childhood of
        // zero means children are born adults; a childhood of a thousand
        // days is a childhood nobody ever sees end, which is the same thing
        // as not having children at all.
        assert!(
            (1..=30).contains(&CHILDHOOD_DAYS),
            "a childhood must end, and must be visible inside a soak"
        );
        // ★ THE CLOCK MUST BE PERSISTENT. `born_day` is stamped from
        // `time_of_day`, which the server resets to
        // settings.world.start_time at EVERY boot — measured on world 109,
        // restarted on its own save: game_day read 0 after both boots having
        // reached ~4 before. A gate on that clock stops aging children the
        // moment anyone restarts the server. The gate reads `Data.tick`.
        let tpgd = ticks_per_game_day(1.0 / 30.0, 48.0);
        assert!(
            (tpgd - 54_000.0).abs() < 1.0,
            "the default server is 54,000 ticks per game day (measured off the live log); got {tpgd}"
        );
        for born in [0u64, 3, 17, 4_000_000] {
            let day = |d: f64| born + (d * tpgd) as u64;
            assert!(
                !has_come_of_age(day(CHILDHOOD_DAYS as f64 - 0.05), Some(born), tpgd),
                "born {born}: not one day early"
            );
            assert!(
                has_come_of_age(day(CHILDHOOD_DAYS as f64), Some(born), tpgd),
                "born {born}: grows up ON the boundary"
            );
            assert!(
                has_come_of_age(day(CHILDHOOD_DAYS as f64 + 10.0), Some(born), tpgd),
                "born {born}: and stays grown up"
            );
            // ★ THE RESTART CASE, stated directly: a tick counter that went
            // BACKWARDS (a rolled-back save) must refuse, not underflow.
            assert!(
                !has_come_of_age(born.saturating_sub(1), Some(born), tpgd),
                "born {born}: a clock that ran backwards must not age a child"
            );
        }
        // A colonist with no birth tick was never a child — founders and
        // settlers arrive grown, and must never be swept up by this rule.
        for now in [0u64, 1, 99, 100_000_000] {
            assert!(
                !has_come_of_age(now, None, tpgd),
                "tick {now}: a colonist with no birth tick must never come of age"
            );
        }
        // ★ AND THE CLOCK IS DERIVED, not assumed: a harness running a
        // different day_length must still age children in GAME days.
        let harness = ticks_per_game_day(1.0 / 30.0, 720.0); // day_length 2.0
        assert!(harness > 0.0 && harness < tpgd, "a faster day is fewer ticks");
        assert!(
            has_come_of_age((CHILDHOOD_DAYS as f64 * harness) as u64, Some(0), harness),
            "childhood must be CHILDHOOD_DAYS of GAME time on any day_length"
        );
        // A degenerate clock must never age everyone instantly.
        assert!(!has_come_of_age(1, Some(0), 0.0), "a zero clock must not age a child");
        assert!(!has_come_of_age(1, Some(0), f64::NAN), "nor a NaN one");
    }

    /// ROW 51 (Ben chartered): personality SHIFTS the evening, never
    /// dictates it. Pinned as a distribution over the whole trait space —
    /// the shipped defect in its sibling row was a constant table nobody
    /// could tell from a live one, so the assertions are about MOVEMENT
    /// relative to the neutral centre, not about any single draw.
    #[test]
    fn personality_shifts_the_evening_without_dictating_it() {
        const SIT: usize = 0;
        const STROLL: usize = 1;
        const VISIT: usize = 2;
        const HOME: usize = 3;
        // Every table keeps the same total, so the draw needs no
        // renormalisation and no bucket can silently vanish.
        for (soc, intro, adv, court) in [
            (false, false, false, false), (true, false, false, false),
            (false, true, false, false), (false, false, true, false),
            (true, false, true, false), (false, true, true, false),
            (false, false, false, true), (true, false, false, true),
            (false, true, false, true), (false, false, true, true),
            (true, false, true, true), (false, true, true, true),
        ] {
            let w = evening_weights(soc, intro, adv, court);
            assert_eq!(
                w.iter().map(|x| u32::from(*x)).sum::<u32>(),
                10,
                "weights must be MOVED, not added: {soc} {intro} {adv} {court} gave {w:?}"
            );
            // ROW 53: the fifth bucket is nonzero EXACTLY while courting.
            assert_eq!(
                w[4] > 0,
                court,
                "COURT must be weighted only for a courting colonist: {w:?}"
            );
        }
        // Identity: a colonist with no strong trait behaves EXACTLY as
        // before this row (fallback = identity, never a copy).
        //
        // ★ PIN-AUDIT (2026-08-29): the assertion below is LOAD-BEARING and
        // must not be removed — against three classic mutants (making a
        // trait branch unconditional, appending an unconditional move,
        // inverting `if introverted`) it is the ONLY assertion in the whole
        // suite that fires, because every other check compares against the
        // constant rather than the mutated neutral.
        assert_eq!(evening_weights(false, false, false, false), EVENING_WEIGHTS_BASE);
        // ★ AND THE GOLDEN VECTOR, spelled out. A 2,400-iteration loop used
        // to sit here comparing `evening_activity` to its own body (the
        // function is now a one-line wrapper), which was equal by
        // construction for any table and any hash. This single line is the
        // independent witness that loop pretended to be: ROW 36b's palette
        // is sit 4 / stroll 3 / visit 2 / home 1.
        assert_eq!(
            EVENING_WEIGHTS_BASE, [4, 3, 2, 1, 0],
            "the ROW 36b palette is the neutral centre; changing it silently \
             re-tunes every colonist's evening. ROW 53's fifth bucket is APPENDED \
             and ZERO, which is what keeps that true"
        );
        // The shifts go the way the trait says.
        let base = EVENING_WEIGHTS_BASE;
        let socl = evening_weights(true, false, false, false);
        assert!(socl[VISIT] > base[VISIT] && socl[SIT] < base[SIT], "sociable visits more");
        let intro = evening_weights(false, true, false, false);
        assert!(intro[HOME] > base[HOME], "the introvert heads home more often");
        let advn = evening_weights(false, false, true, false);
        assert!(advn[STROLL] > base[STROLL] && advn[SIT] < base[SIT], "the restless walk");
        // ★ AND NOBODY IS DICTATED TO. Every trait profile must still
        // produce EVERY activity across a population — a trait that
        // forced an outcome would just replace one uniform town with
        // another, which is the failure this row exists to avoid.
        for (soc, intro_f, adv) in [
            (false, false, false), (true, false, false),
            (false, true, false), (false, false, true),
        ] {
            let w = evening_weights(soc, intro_f, adv, false);
            let mut seen = [false; 4];
            for uid in 1..400u64 {
                seen[evening_activity_weighted(uid, 3, w) as usize] = true;
            }
            assert!(
                seen.iter().all(|s| *s),
                "profile {soc} {intro_f} {adv} (weights {w:?}) never produced some activity"
            );
            // ROW 53: a COURTING colonist still gets a whole life —
            // courtship SHIFTS the evening the way a trait does, it does
            // not replace it.
            let wc = evening_weights(soc, intro_f, adv, true);
            let mut seen5 = [false; 5];
            for uid in 1..400u64 {
                seen5[evening_activity_weighted(uid, 3, wc) as usize] = true;
            }
            assert!(seen5[4], "a courting colonist must actually court: {wc:?}");
            assert!(
                seen5.iter().filter(|s| **s).count() >= 3,
                "courtship must not swallow the evening: {wc:?} produced {seen5:?}"
            );
        }
        // A degenerate table falls back to the base SHAPE, not to a
        // constant activity — and must not divide by zero.
        let mut seen = [false; 4];
        for uid in 1..400u64 {
            seen[evening_activity_weighted(uid, 1, [0, 0, 0, 0, 0]) as usize] = true;
        }
        assert!(seen.iter().all(|s| *s), "the zero-table fallback must be the base palette");
    }

    /// ★★ ROW 53: THE FIFTH BUCKET CHANGES NOBODY WHO IS NOT COURTING.
    ///
    /// The palette is drawn by EVERY colonist EVERY evening, so a fifth
    /// bucket that shifted the draw would silently re-tune the whole town
    /// — and every distribution pin above would move with it, a change that
    /// hides inside its own witnesses.
    ///
    /// Identity needs BOTH halves and neither alone is sufficient: the new
    /// weight must be ZERO, and the hash's modulo must see the SAME TOTAL.
    /// The reference is a hand-written copy of the SHIPPED four-bucket draw,
    /// not a call back into the function under test — a pin that asserts a
    /// function equals its own body is testing nothing, which is exactly
    /// what the ROW 51 pin audit found in this palette.
    #[test]
    fn the_fifth_bucket_changes_nobody_who_is_not_courting() {
        fn shipped_draw(uid_raw: u64, epoch: u64, w: [u8; 4]) -> u8 {
            let h = uid_raw
                .wrapping_mul(0x9E37_79B9_7F4A_7C15)
                .wrapping_add(epoch.wrapping_mul(0xBF58_476D_1CE4_E5B9));
            let total = u64::from(w[0]) + u64::from(w[1]) + u64::from(w[2]) + u64::from(w[3]);
            if total == 0 {
                return shipped_draw(uid_raw, epoch, [4, 3, 2, 1]);
            }
            let mut roll = (h >> 32) % total;
            for (i, weight) in w.iter().enumerate() {
                let weight = u64::from(*weight);
                if roll < weight {
                    return i as u8;
                }
                roll -= weight;
            }
            3
        }
        for (soc, intro, adv) in [
            (false, false, false), (true, false, false),
            (false, true, false), (false, false, true),
            (true, false, true), (false, true, true),
        ] {
            let w5 = evening_weights(soc, intro, adv, false);
            let w4 = [w5[0], w5[1], w5[2], w5[3]];
            assert_eq!(w5[4], 0, "an uncommitted colonist must carry no COURT weight");
            assert_eq!(
                w4.iter().map(|x| u32::from(*x)).sum::<u32>(),
                10,
                "the modulo's divisor must be unchanged, or every draw moves"
            );
            for uid in 1..=1_000u64 {
                for epoch in 0..12u64 {
                    assert_eq!(
                        evening_activity_weighted(uid, epoch, w5),
                        shipped_draw(uid, epoch, w4),
                        "uid {uid} epoch {epoch} profile {soc}/{intro}/{adv}: the fifth \
                         bucket moved an uncommitted colonist's evening"
                    );
                }
            }
        }
    }

    /// ★ ROW 52 v2: the forge gate, both directions, on the THREE-tool par
    /// and the crew cap. v1's own soak disposed it honestly: the forge
    /// worked, made 64 tools on one world, and the town still named nobody
    /// Craft. Two measured causes, both pinned here.
    #[test]
    fn the_forge_lights_only_when_the_town_is_short_of_tools() {
        let roster = 26u32;
        let par = TOOL_PAR_PER_COLONIST * roster;
        let short = [0u32, 0, 0];
        let full = [par, par, par];
        let ok = craft_verdict(true, 5, false, 10, short, roster, 0, 3);
        assert!(ok.fired, "no tools for twenty-six people: work");
        assert!(ok.output.is_some(), "a firing must say WHICH tool it is for");
        for (v, why) in [
            (craft_verdict(false, 5, false, 10, short, roster, 0, 3), "disabled"),
            (craft_verdict(true, 0, false, 10, short, roster, 0, 3), "no_workshop"),
            (craft_verdict(true, 5, true, 10, short, roster, 0, 3), "station_busy"),
            (craft_verdict(true, 5, false, 10, short, roster, 3, 3), "crew_full"),
            (craft_verdict(true, 5, false, 0, short, roster, 0, 3), "no_wood"),
            (craft_verdict(true, 5, false, 10, full, roster, 0, 3), "tools_at_par"),
        ] {
            assert!(!v.fired, "{why}: must refuse");
            assert_eq!(v.deciding, why, "the refusal must NAME itself");
            assert!(v.output.is_none(), "{why}: a refusal forges nothing");
        }
        // ★ THE CREW CAP REFUSES BEFORE THE WOOD CHECK. A guard that spends
        // first starves what it protects (this project shipped exactly that
        // in the farm and had to move the test into the push predicate), so
        // a full crew must not be able to consume a station's turn.
        assert_eq!(
            craft_verdict(true, 5, false, 0, short, roster, 9, 3).deciding,
            "crew_full",
            "a full crew must refuse BEFORE the wood check, not after"
        );
        // ★ THE PAR IS RENEWABLE BY GROWTH - the reason this row needs no
        // tool wear. Pinned as the property over every plausible roster.
        for r in 1..=60u32 {
            let at = TOOL_PAR_PER_COLONIST * r;
            assert!(
                !craft_verdict(true, 3, false, 99, [at, at, at], r, 0, 9).fired,
                "roster {r}: a town holding its par must stop"
            );
            assert!(
                craft_verdict(true, 3, false, 99, [at, at, at], r + 1, 0, 9).fired,
                "roster {r}: ONE more colonist must reopen the forge"
            );
        }
        // Wood is a real cost.
        for wood in 0..CRAFT_WOOD_PER_TOOL {
            assert_eq!(
                craft_verdict(true, 3, false, wood, short, roster, 0, 9).deciding,
                "no_wood"
            );
        }
    }

    /// ★ ROW 52 v2: the forge makes what the town is SHORTEST of, and the
    /// choice is a total order. A generator that picks by iteration order
    /// is a determinism defect; a generator whose choice disagrees with
    /// what the completion produces is the churn shape.
    #[test]
    fn the_forge_makes_the_tool_the_town_lacks() {
        let roster = 10u32;
        let par = TOOL_PAR_PER_COLONIST * roster;
        // Shortest wins, whichever slot it is in.
        assert_eq!(tool_shortfall([par, 0, par], roster), Some(1));
        assert_eq!(tool_shortfall([0, par, par], roster), Some(0));
        assert_eq!(tool_shortfall([par, par, 0], roster), Some(2));
        assert_eq!(tool_shortfall([5, 3, 9], roster), Some(1), "3 is the fewest");
        // A complete kit asks for nothing.
        assert_eq!(tool_shortfall([par, par, par], roster), None);
        assert_eq!(tool_shortfall([par + 9, par, par], roster), None);
        // ★ TIES ARE A TOTAL ORDER, not iteration order: equal shortfalls
        // must always resolve to the lowest index, on every run.
        for _ in 0..64 {
            assert_eq!(tool_shortfall([0, 0, 0], roster), Some(0));
            assert_eq!(tool_shortfall([par, 2, 2], roster), Some(1));
        }
        // ★ AND IT TERMINATES: forging the scarcest each time must reach a
        // complete kit and stop. Under any starting state.
        for start in [[0u32, 0, 0], [par, 0, 0], [3, 1, 7], [par, par, par - 1]] {
            let mut held = start;
            let mut forged = 0u32;
            while let Some(i) = tool_shortfall(held, roster) {
                held[i] += 1;
                forged += 1;
                assert!(forged <= 3 * par + 1, "the forge must terminate, not grind");
            }
            assert!(
                held.iter().all(|h| *h >= par),
                "termination must mean the kit is COMPLETE, not merely that we gave up"
            );
        }
    }

    /// ★ ROW 52 FIX (caught in the row's FIRST game-hour on world 111, then
    /// proven in a matched A/B): the forge's par must be able to SEE the
    /// forge's own output. v1 read a stockpile-scoped count while the
    /// completion drops the tool at the workshop, so `tools_held` stayed 0
    /// after tools were made. LIVE EVIDENCE: world 111 (blind par) crafted
    /// 64 tools and still read tools_held=0; world 112 (fixed), same arm and
    /// seed, read tools_held=21. The blind version would have eaten every
    /// log in the town - and its 64 stray items inverted hauling from
    /// 2,833 to 14,039 arrivals, swamping the whole labour economy.
    ///
    /// Pinned as the TERMINATION property, because that is what actually
    /// failed.
    #[test]
    fn the_forge_can_see_its_own_output() {
        let roster = 26u32;
        let par = TOOL_PAR_PER_COLONIST * roster;
        // v1's blind reading: held never rises, so the gate never refuses.
        for _ in 0..200 {
            assert!(
                craft_verdict(true, 5, false, 99, [0, 0, 0], roster, 0, 9).fired,
                "the SHIPPED reading never stops - this is the churn engine, asserted"
            );
        }
        // The fixed reading counts what the town HOLDS, and terminates.
        let mut held = [0u32; 3];
        let mut forged = 0u32;
        while craft_verdict(true, 5, false, 99, held, roster, 0, 9).fired && forged < 10_000 {
            let i = tool_shortfall(held, roster).expect("fired implies a shortfall");
            held[i] += 1;
            forged += 1;
        }
        assert_eq!(
            forged,
            3 * par,
            "the forge must make exactly the town's kit and then stop; it made {forged}"
        );
        assert_eq!(
            craft_verdict(true, 5, false, 99, held, roster, 0, 9).deciding,
            "tools_at_par"
        );
    }

    /// ★★ RETENTION IS MEASURED FROM THE BED CELL — IN LITERALS.
    ///
    /// REPLACES A DEAD PIN. The previous version of this test computed
    /// `r = ARRIVE_DIST + SLEEP_HYSTERESIS` and
    /// `target = approach_target(bed, stance)` — the two expressions the
    /// implementation itself evaluates — and then asserted the
    /// implementation against them. That is the implementation compared with
    /// itself: setting `SLEEP_HYSTERESIS = 0.0`, the zero-width band the pin
    /// was written to forbid, moved both sides together and left it GREEN
    /// (the probe lands at distance² 6.25 against r² 6.25, and `6.25 > 6.25`
    /// is false). Every number below is a hardcoded literal for that reason.
    #[test]
    fn the_retention_band_is_measured_from_the_bed_cell() {
        let bed = Vec3::new(10, 10, 5);

        // The band's width, stated as a literal. If either constant moves,
        // this fails here rather than silently widening every case below.
        assert_eq!(
            ARRIVE_DIST + SLEEP_HYSTERESIS,
            3.0,
            "the retention radius is no longer 3.0; every literal in this pin was chosen \
             against that width"
        );
        assert!(
            SLEEP_HYSTERESIS > 0.0,
            "a zero-width hysteresis band makes arrival and release the same boundary, and \
             the latch flaps Arrived<->Traveling forever"
        );

        // THE ANCHOR ITSELF. A bed is registered at a FEET cell, so a body
        // lying in it is at the cell centre with NO z offset. Literal.
        assert_eq!(
            lying_target(bed),
            Vec3::new(10.5, 10.5, 5.0),
            "the retention anchor is not the bed cell — if this is (…, 6.0) the anchor is the \
             ARRIVAL approach target again, a full block above the sleeping body"
        );

        // ── THE REGRESSION THIS FIX EXISTS FOR ──────────────────────────
        // The measured upper-storey fall: dz = -1.98, dxy = 0.72 from the
        // bed cell. Distance from the bed cell is sqrt(1.98² + 0.72²) =
        // 2.107 — comfortably inside 3.0, so the sleeper HOLDS.
        let fallen = Vec3::new(10.5 + 0.72, 10.5, 5.0 - 1.98);
        assert!(
            !sleep_displaced(fallen, bed),
            "the measured upper-storey fall (dz=-1.98, dxy=0.72) must HOLD: it is 2.107 from \
             the bed cell. Measured from the arrival anchor it reads 3.066 and releases on a \
             0.066 margin — that artefact is what produced the SLEEP UNHOLDABLE strikes"
        );
        // And prove the OLD anchor really would have released it, so this
        // pin fails if anyone re-anchors on the approach target.
        let arrival_anchor = Vec3::new(10.5, 10.5, 6.0);
        assert!(
            fallen.distance(arrival_anchor) > 3.0,
            "sanity: from the arrival anchor this same body is past the band — that is the \
             defect being pinned against"
        );

        // ── THE FALSE "LYING" READING, the other direction ──────────────
        // A colonist on the roof 3.5 blocks above their own bed must NOT
        // count as in it; from the arrival anchor they read only 2.5.
        let on_the_roof = Vec3::new(10.5, 10.5, 5.0 + 3.5);
        assert!(
            sleep_displaced(on_the_roof, bed),
            "a body 3.5 blocks above its bed must be DISPLACED — otherwise rest keeps banking \
             and the bed census counts a rooftop figure as `lying`, which is a false reading \
             of the exact acceptance criterion the census protects"
        );
        assert!(
            on_the_roof.distance(arrival_anchor) < 3.0,
            "sanity: the arrival anchor would have called this rooftop body NOT displaced"
        );

        // ── ORDINARY HOLDS AND RELEASES, all literal distances ──────────
        for (body, dist, hold) in [
            (Vec3::new(10.5, 10.5, 5.0), 0.0, true),   // dead centre
            (Vec3::new(12.5, 10.5, 5.0), 2.0, true),   // 2.0 aside
            (Vec3::new(13.4, 10.5, 5.0), 2.9, true),   // just inside
            (Vec3::new(13.6, 10.5, 5.0), 3.1, false),  // just outside
            (Vec3::new(10.5, 10.5, 1.0), 4.0, false),  // fell 4 blocks
            (Vec3::new(16.5, 10.5, 5.0), 6.0, false),  // the 6-block defect
        ] {
            assert_eq!(
                !sleep_displaced(body, bed),
                hold,
                "body at {body:?} is {dist} from the bed cell; expected hold={hold}"
            );
        }
    }

    /// ★★ THE CHILDHOOD GATE MUST NOT MOVE WITH FRAME RATE.
    ///
    /// `has_come_of_age` divides a PERSISTENT tick count by
    /// `ticks_per_game_day`, which the sweep used to build from
    /// `Read<DeltaTime>` — the measured frame delta, clamped only by
    /// `MAX_GAME_DT = 1/5`. A persistent monotonic numerator over a
    /// wall-clock denominator: the graduation tick moved with load, and
    /// because the sweep evaluates every child in ONE pass, a single hitching
    /// frame graduated the whole cohort irreversibly.
    #[test]
    fn the_childhood_gate_does_not_move_with_frame_rate() {
        // The nominal server, stated in literals: 86400 game-seconds per day
        // over (1/30 * 48) = 1.6 game-seconds per tick = 54,000 ticks.
        let nominal = ticks_per_game_day(1.0 / 30.0, 48.0);
        assert_eq!(nominal, 54_000.0, "the measured default-server figure moved");

        // A hitching frame at the MAX_GAME_DT clamp. This is what the sweep
        // used to hand the gate.
        let hitching = ticks_per_game_day(0.15, 48.0);
        assert!(
            (hitching - 12_000.0).abs() < 1.0,
            "a hitching frame gives {hitching} ticks per game day against the nominal 54,000 \
             — a 4.5x error in the denominator of an irreversible gate"
        );

        // Four game days at the nominal rate — a child who is exactly of age.
        let four_days = 4 * 54_000;
        assert_eq!(CHILDHOOD_DAYS, 4, "the literals below assume a 4-day childhood");

        // The defect, stated: at the hitching denominator a child who has
        // lived only 60,000 ticks — 1.11 game days at the real rate —
        // reads as five days old and graduates.
        assert!(
            has_come_of_age(60_000, Some(0), hitching),
            "sanity: this is the WRONG reading the wall-clock denominator produced"
        );
        assert!(
            !has_come_of_age(60_000, Some(0), nominal),
            "1.11 game days is not a childhood — a child must NOT come of age here"
        );
        assert!(
            has_come_of_age(four_days as u64, Some(0), nominal),
            "a child who has lived four full game days must come of age"
        );

        // And the call site must feed it the NOMINAL rate, not the frame
        // delta. Needles built at runtime.
        let src = include_str!("bastion_jobs.rs");
        let nominal_call = format!("1.0 / crate::{} as f64", "SIM_TPS");
        // ROW 53: TWO call sites now, not one — the childhood gate and the
        // courtship clock, which is deliberately the same clock (a
        // persistent numerator needs a persistent denominator). The count
        // is still exact: changing EITHER site back to the measured frame
        // delta drops it to 1 and fails here.
        assert_eq!(
            src.matches(&nominal_call).count(),
            2,
            "a game-day gate no longer derives ticks-per-game-day from the nominal tick \
             rate — if it is reading dt again, one slow frame graduates the whole cohort \
             (and seals every courtship at once)"
        );
        let frame_delta = format!("ticks_per_game_day(\n                        f64::from({}.0),", "dt");
        assert_eq!(
            src.matches(&frame_delta).count(),
            0,
            "the childhood sweep is reading the measured frame delta again"
        );
    }

    /// ★★ AN ORPHAN IS NOT RAISED INTO A DEAD LANE.
    ///
    /// The sweep tie-broke equally-short lanes on `format!("{w:?}")`. Build,
    /// Chop and Craft all sit at 0 practitioners in a young colony and
    /// "Build" < "Chop" < "Craft", so every parentless child resolved to
    /// Build — the lane the row's measurements call dead. The tiebreak is now
    /// live demand: unclaimed jobs standing on the board.
    #[test]
    fn an_orphan_is_not_raised_into_a_lane_with_no_work() {
        use common::bastion::WorkType as W;
        // The exact shipped shape: three lanes tied at zero practitioners,
        // and only one of them has work. Alphabetically Build wins; by
        // demand, Craft must.
        let lanes = [(W::Build, 0usize, 0usize), (W::Chop, 0, 0), (W::Craft, 0, 37)];
        assert_eq!(
            scarcest_lane(&lanes),
            Some(W::Craft),
            "the orphan was raised into a lane with ZERO open jobs while 37 stood unclaimed \
             elsewhere — that is the alphabetical tiebreak choosing, not the colony"
        );
        // Headcount still OUTRANKS demand: a lane nobody works at all is
        // scarcer than a busy lane with practitioners.
        let lanes = [(W::Build, 0, 0), (W::Craft, 5, 99)];
        assert_eq!(
            scarcest_lane(&lanes),
            Some(W::Build),
            "scarcity of PEOPLE is the primary key; demand only breaks ties"
        );
        // Fully degenerate input stays deterministic rather than picking by
        // hash order.
        let lanes = [(W::Chop, 2, 4), (W::Build, 2, 4)];
        assert_eq!(scarcest_lane(&lanes), Some(W::Build));
        assert_eq!(scarcest_lane(&[]), None);
    }

    /// ★★ THE STALL EXEMPTION IS A 3D TEST.
    ///
    /// `steer_at_own_feet` zeroes the stall clock. Tested in XY only, it
    /// fired for a colonist who had fallen through an upper-storey floor
    /// (dz = -2.0, dxy = 0.72), so `STUCK_TIMEOUT` never elapsed, strikes
    /// never accrued, and the escalation discard was unreachable — the
    /// silent unbounded loop. Literals throughout.
    #[test]
    fn the_stall_exemption_sees_a_vertical_displacement() {
        let body = Vec3::new(10.5, 10.5, 5.0);
        // THE DEFECT: two blocks below the steer target, 0.72 aside. Under
        // an XY-only test this reads as "already there".
        let fallen_through_floor = Vec3::new(10.5 + 0.72, 10.5, 5.0 + 2.0);
        assert!(
            !steer_is_at_own_feet(fallen_through_floor, body),
            "a colonist 2 blocks below his steer target is NOT standing on it — exempting him \
             pins the stall clock to zero and the escalation can never fire"
        );
        assert!(
            fallen_through_floor.xy().distance(body.xy()) < 1.2,
            "sanity: XY-only, this is the exemption firing — that is the defect"
        );
        // THE INTENT, preserved: a body genuinely at its target is exempt,
        // including across the one-block anchor differences this file uses.
        assert!(
            steer_is_at_own_feet(body, body),
            "a body exactly on its steer target has nothing to walk to"
        );
        assert!(
            steer_is_at_own_feet(Vec3::new(10.5, 10.5, 6.0), body),
            "a one-block anchor difference (approach target vs lying target) must stay exempt, \
             or the stall clock starts on colonists standing where they were sent"
        );
        assert!(
            !steer_is_at_own_feet(Vec3::new(13.0, 10.5, 5.0), body),
            "2.5 blocks away horizontally is a real walk, not a standstill"
        );
    }

    /// ★★ EVERY FARM PUSH PAYS THE BUDGET, AND EVERY DEBIT IS GUARDED.
    ///
    /// The volunteer-crop arm was the one farm push site reading a bare
    /// `!occupied.contains(&cpos)` — no `cell_free` churn filter and no
    /// `open_budget` debit — while all five siblings used
    /// `cell_free(..) && open_budget > 0`. Volunteer jobs are ordinary
    /// unclaimed Farm jobs inside the plot, so `open_by_plot` COUNTS them:
    /// an adopted village field with hundreds of standing crops drove
    /// `open_budget` to 0 permanently and that plot could never mint another
    /// till, sow or harvest. Found independently by two reviewers.
    ///
    /// CODE ONLY — an earlier pin in this file was dead because its needle
    /// matched the surrounding doc comment rather than a statement.
    #[test]
    fn every_farm_push_debits_the_plot_budget_behind_a_guard() {
        let src = include_str!("bastion_jobs.rs");
        let code: String = src
            .lines()
            .filter(|l| !l.trim_start().starts_with("//"))
            .collect::<Vec<_>>()
            .join("\n");
        let debit = format!("open_budget {} 1;", "-=");
        let guard_c = format!("cell_free(cpos) && open_budget {} 0", ">");
        let guard_g = format!("cell_free(gpos) && open_budget {} 0", ">");
        let debits = code.matches(&debit).count();
        let guards = code.matches(&guard_c).count() + code.matches(&guard_g).count();
        assert!(debits > 0, "the farm budget is no longer debited anywhere");
        assert_eq!(
            debits, guards,
            "{debits} farm budget debits against {guards} guards — a push site is spending the \
             plot's budget without first proving the cell is free, or minting without paying. \
             A guard placed after its debit starves the plot (ROW 50 rank 1)"
        );
        let bare = format!("!occupied.contains(&{})", "cpos");
        assert_eq!(
            code.matches(&bare).count(),
            0,
            "a farm push site is back to the bare occupancy check: it mints unbudgeted jobs \
             that `open_by_plot` still counts, which pins that plot's open_budget to 0 forever"
        );
    }

    /// ★★ THE FORGE CAP'S DEGENERATE SETTINGS.
    ///
    /// `BASTION_FORGE_CREW=0` used to parse straight through to a cap of 0,
    /// making the mint gate's `crew >= cap` read `0 >= 0` — true always. The
    /// forge went permanently dark with no refusal naming the cause. The
    /// derived path had floored at 1 all along; only the override did not.
    #[test]
    fn the_forge_cap_refuses_its_degenerate_settings() {
        // The derived path, at both ends of the roster range.
        assert_eq!(forge_crew_cap(0), 1, "an empty roster must still admit one smith");
        assert!(
            forge_crew_cap(0) >= 1 && forge_crew_cap(240) >= 1,
            "a cap of 0 makes `crew >= cap` unconditionally true and the forge never lights"
        );
        // The floor is applied to the OVERRIDE too, not just the default.
        // (The env is read once into a OnceLock, so drive the clamp itself.)
        let clamp = |v: usize| v.max(1);
        assert_eq!(clamp(0), 1, "BASTION_FORGE_CREW=0 must not survive as a cap of 0");
        let src = include_str!("bastion_jobs.rs");
        let floored = format!(".map(|v| v.max({}))", "1");
        assert_eq!(
            src.matches(&floored).count(),
            1,
            "the forge cap's env override is no longer floored — BASTION_FORGE_CREW=0 would \
             darken the forge permanently"
        );
    }

    /// ★★ THE DISPLACEMENT STRIKE CAP HAD NO PIN AT ALL.
    ///
    /// `SLEEP_DISPLACE_STRIKE_CAP` gates how many times one sleeper may be
    /// pushed off one bed before the town gives that bed up. Nothing
    /// anywhere asserted its value or its direction, so `CAP = 0` or
    /// `CAP = 1` — which drop the bed on the FIRST jostle, before any
    /// retry — would have shipped with the whole suite green. That is the
    /// degenerate setting the pin has to forbid, not the nominal one.
    #[test]
    fn the_sleep_displacement_cap_survives_a_single_jostle() {
        assert!(
            SLEEP_DISPLACE_STRIKE_CAP >= 2,
            "a cap below 2 condemns a bed on the first displacement — one shove from a \
             passing colonist, one physics tick at a doorway, and the sleeper loses the bed \
             with no retry. The cap exists to distinguish a bed that CANNOT be held from a \
             bed that was merely bumped"
        );
        assert!(
            SLEEP_DISPLACE_STRIKE_CAP <= 64,
            "an effectively unbounded cap means a genuinely unholdable bed is retried forever, \
             which is the loop the cap was added to stop"
        );
        // The comparison must be a >= cap test at exactly one site: a `>`
        // would silently grant one extra strike, a second site would mean
        // two different caps in one mechanism.
        let src = include_str!("bastion_jobs.rs");
        let needle = format!("{} {} {}", "strikes", ">=", "SLEEP_DISPLACE_STRIKE_CAP");
        assert_eq!(
            src.matches(&needle).count(),
            1,
            "the strike cap is no longer consulted exactly once with >= — either it is \
             unenforced or two sites disagree about the bound"
        );
    }

    /// ★ REVIEW FIX PIN (2026-08-29): every lane is covered, and the guard
    /// is the COMPILER, not this test.
    ///
    /// The adversarial review found three hand-written lists of `WorkType`'s
    /// variants that had fallen behind when `Craft` was appended. A unit
    /// test cannot catch that class of defect on its own — it would need its
    /// own copy of the same list, which is the very thing that goes stale.
    /// So `WorkType::lane_index` is a match with no wildcard: adding a
    /// variant without adding it to `ALL` fails to COMPILE. This test proves
    /// the two agree, which is what makes the compile-time guard meaningful.
    #[test]
    fn every_work_lane_is_covered_exactly_once() {
        use common::bastion::WorkType;
        assert_eq!(WorkType::ALL.len(), WorkType::COUNT);
        // ★ NOTE ON WHAT THIS TEST CAN AND CANNOT DO. Enumerating from `ALL`
        // cannot prove `ALL` is complete — my first version of this pin did
        // exactly that and passed happily when `Craft` was dropped and
        // `COUNT` set to 7. The completeness guard is the compile-time
        // `_ALL_AGREES_WITH_LANE_INDEX` in common/src/bastion.rs, backed by
        // two wildcard-free matches (`lane_index`, `label`) that make a new
        // variant a compile error until it is handled here.
        //
        // What THIS test adds is the consumer coverage below: every lane in
        // `ALL` must actually route to a skill, a priority and a label — the
        // failure mode that put Blacksmith in a lane with no work.
        let mut seen = [false; WorkType::COUNT];
        for w in WorkType::ALL {
            let i = w.lane_index();
            assert!(i < WorkType::COUNT, "{w:?}: index {i} out of range");
            assert!(!seen[i], "{w:?}: index {i} used twice — ALL has a duplicate");
            seen[i] = true;
        }
        assert!(seen.iter().all(|s| *s), "ALL and lane_index disagree");
        // Craft specifically: it is the variant all three stale lists missed,
        // and the one whose absence sent every orphan into a dead lane.
        assert!(
            WorkType::ALL.contains(&WorkType::Craft),
            "Craft must be in ALL — its omission is the defect this exists for"
        );
        // Every lane has a distinct label, or the inspector and the
        // profession census cannot tell two trades apart.
        let mut labels: Vec<&str> = WorkType::ALL.iter().map(|w| w.label()).collect();
        labels.sort_unstable();
        let before = labels.len();
        labels.dedup();
        assert_eq!(before, labels.len(), "two lanes share a label");
        // ★ AND THE CONSUMERS: every lane must route to its own skill and be
        // settable as a priority, or a lane can exist that nobody can train
        // or prefer — which is exactly how Blacksmith ended up in a dead one.
        for w in WorkType::ALL {
            let mut sk = common::bastion::ColonistSkills::default();
            sk.grant_xp(w, 500.0);
            assert!(sk.level_for(w) > 0, "{w:?}: xp must train a skill");
            let p = common::bastion::WorkPriorities::in_lane(w);
            assert_eq!(p.get(w), 4, "{w:?}: in_lane must prefer its own trade");
            assert_eq!(
                common::bastion::WorkPriorities::childhood().get(w),
                0,
                "{w:?}: a child must refuse every lane"
            );
        }
    }

    /// ★ ROW 52: the lane must be REACHABLE, which is the failure this row
    /// exists to fix. Measured baseline before the row: across two soaked
    /// worlds and ~54 profession namings the town named only Haul, Farm,
    /// Cook, Guard and Mine — Build NEVER ONCE — while Blacksmith's lane
    /// WAS Build. Renaming the lane without giving it work would repeat
    /// that exactly, so these assert the wiring end to end.
    #[test]
    fn a_blacksmith_has_a_lane_with_work_in_it() {
        use common::bastion::{WorkPriorities, WorkType};
        use common::rtsim::Profession;
        assert_eq!(
            WorkPriorities::work_for_profession(Profession::Blacksmith),
            Some(WorkType::Craft),
            "a blacksmith must map to the lane the forge mints into"
        );
        // In lane, and ONLY in lane: an in-lane smith outbids the town,
        // and nobody else is promoted into the forge by accident.
        let smith = WorkPriorities::in_lane(WorkType::Craft);
        assert_eq!(smith.get(WorkType::Craft), 4, "the smith prefers the forge");
        for other in [
            WorkType::Farm, WorkType::Cook, WorkType::Build,
            WorkType::Haul, WorkType::Mine, WorkType::Chop, WorkType::Guard,
        ] {
            assert!(
                WorkPriorities::in_lane(other).get(WorkType::Craft) < 4,
                "{other:?} must not read as in-lane for the forge"
            );
            assert!(
                WorkPriorities::in_lane(other).get(WorkType::Craft) > 0,
                "{other:?} must still be ABLE to craft — cross-domain work stays possible"
            );
        }
        // The lane routes to its own skill and its own label, or the
        // profession derivation and the inspector cannot name it.
        let mut sk = common::bastion::ColonistSkills::default();
        sk.grant_xp(WorkType::Craft, 500.0);
        assert!(
            sk.level_for(WorkType::Craft) > 0,
            "craft XP must train the craft skill, or a smith never gets good"
        );
        for w in [WorkType::Farm, WorkType::Build, WorkType::Haul, WorkType::Cook] {
            assert_eq!(
                sk.level_for(w), 0,
                "{w:?} must NOT be trained by craft work — lanes must stay separable"
            );
        }
        assert_eq!(WorkType::Craft.label(), "craft");
        // A child still refuses the forge like every other lane.
        assert_eq!(WorkPriorities::childhood().get(WorkType::Craft), 0);
        assert!(WorkPriorities::childhood().is_all_zero());
    }

    /// ROW 50 (review rank 7): the plaza census must count the SQUARE. The
    /// ring radius it classifies against has to track the seating, or a
    /// city's own benches read as "out of town".
    #[test]
    fn the_plaza_census_measures_the_square_it_seats() {
        let anchor = Vec3::new(100, 200, 60);
        for rank in 0..500usize {
            let seat = gathering_spot(anchor, rank);
            let cheb = (seat.x - anchor.x).abs().max((seat.y - anchor.y).abs());
            assert!(
                cheb <= gathering_ring_radius(rank),
                "rank {rank} seats at {cheb} but its ring is {}",
                gathering_ring_radius(rank)
            );
        }
        // …and a STROLL seat must fall OUTSIDE the square of any plausible
        // colony, or the census cannot tell a walk from a sit — which is
        // the whole defect: strollers were counted as plaza occupancy.
        for pop in [8usize, 24, 96, 200] {
            for rank in 0..pop {
                let stroll = gathering_spot(anchor, rank + STROLL_BAND);
                let cheb = (stroll.x - anchor.x).abs().max((stroll.y - anchor.y).abs());
                assert!(
                    cheb > gathering_ring_radius(pop) + 1,
                    "pop {pop} rank {rank}: a stroll seat at {cheb} is inside the square"
                );
            }
        }
    }

    /// ROW 43 (THE CHEF): the kitchen is a POST with a crew, not a chore
    /// the whole town picks up. Measured failure: 9 of 25 colonists named
    /// Cook. Both directions — a hamlet still eats, a city never turns
    /// into a kitchen brigade.
    #[test]
    fn the_kitchen_has_a_crew_not_a_queue() {
        assert_eq!(kitchen_crew_cap(0), 1, "even a colony of nobody keeps one post open");
        assert_eq!(kitchen_crew_cap(8), 1, "a hamlet has ONE cook");
        assert_eq!(kitchen_crew_cap(12), 1);
        assert_eq!(kitchen_crew_cap(24), 2, "a town of 24 gets a second pair of hands");
        assert_eq!(kitchen_crew_cap(60), 5);
        // The mandate's own bar: the kitchen must never be able to swallow
        // the town. At every plausible roster the crew stays a small
        // minority — this is what makes "the chef cooks" nameable.
        for roster in 1..=120usize {
            let cap = kitchen_crew_cap(roster);
            assert!(cap >= 1, "roster {roster}: someone must be able to cook");
            assert!(
                cap * 4 <= roster.max(4),
                "roster {roster}: cap {cap} is more than a quarter of the town — that is not a chef, that is a canteen"
            );
        }
        // Monotone: growing the town never REDUCES its kitchen.
        for r in 0..120usize {
            assert!(kitchen_crew_cap(r) <= kitchen_crew_cap(r + 1));
        }
    }

    /// ROW 40 (farm churn): the guard offers a cell a real chance and then
    /// stops — and it must NEVER become a permanent condemnation, because
    /// a tilled cell, a loaded chunk or a new season all make a moot cell
    /// workable again.
    #[test]
    fn a_churning_farm_cell_is_rested_but_never_condemned() {
        assert!(!farm_cell_is_churning(None), "an untouched cell is offered");
        for n in 0..FARM_MOOT_LIMIT {
            assert!(
                !farm_cell_is_churning(Some(&n)),
                "moot {n} is still within the retry window — a transient deserves retries"
            );
        }
        assert!(
            farm_cell_is_churning(Some(&FARM_MOOT_LIMIT)),
            "at the limit the cell must stop being offered — this is the churn engine's off switch"
        );
        assert!(farm_cell_is_churning(Some(&138)), "the measured churn case");
        // THE RELEASE VALVES, asserted rather than assumed: halving returns
        // a cell to service, and a success clears it outright.
        let mut n = 138u32;
        let mut days = 0;
        while farm_cell_is_churning(Some(&n)) {
            n /= 2;
            days += 1;
            assert!(days < 20, "a cell must not stay rested forever");
        }
        assert!(days <= 8, "even the worst measured cell returns within a week: {days}");
        assert!(!farm_cell_is_churning(None), "clearing on success re-offers immediately");
    }

    /// ROW 36f (review): NO TWO COLONISTS IN ONE CHAIR. The palette must
    /// preserve `gathering_spot`'s rank→cell injectivity across every
    /// activity at once — the first version broke it two ways (STROLL's
    /// +24 collided with a real seat past 24 colonists; VISIT sat exactly
    /// ON the neighbour's bench). Simulates a whole colony choosing
    /// different evenings simultaneously and asserts every cell distinct.
    #[test]
    fn every_evening_seat_is_its_own_cell() {
        // ROW 53: the eight cells are now a named constant with three
        // consumers; a fourth hand-written copy here is how this palette
        // earned its collision history in the first place.
        const AROUND: [(i32, i32); 8] = BENCH_AROUND;
        const COLONY: usize = 30;
        let anchor = Vec3::new(1000, 2000, 40);
        // ROW 53: `senior` is the rank a COURT seat is aimed at.
        let seat = |act: u8, rank: usize, senior: usize| -> Vec3<i32> {
            match act {
                1 => gathering_spot(anchor, rank + STROLL_BAND),
                2 => {
                    let bench = gathering_spot(anchor, rank ^ 1);
                    let (dx, dy) = AROUND[rank % 8];
                    bench + Vec3::new(dx, dy, 0)
                },
                4 => court_seat(anchor, senior, COLONY),
                _ => gathering_spot(anchor, rank),
            }
        };
        // ★★ ROW 53, THE THEOREM THE COURT SEAT IS BUILT ON, swept over the
        // whole seniority space at seven colony sizes rather than sampled:
        // a court seat is NEVER anybody's bench, VISIT seat, STROLL seat or
        // another couple's court seat, and is always BESIDE its own
        // senior's bench.
        //
        // The gathering ring's benches are only TWO cells apart, so the
        // eight-cell neighbourhood of one bench routinely contains another
        // — measured, `gathering_spot(22) + (-1,-1) == gathering_spot(8)`
        // exactly — which is why the offset has to be dealt rather than
        // indexed. (It is also why the shipped VISIT arm collides; see the
        // note below.)
        for n in [8usize, 12, 20, 30, 50, 80, 120] {
            let benches: std::collections::HashSet<Vec3<i32>> =
                (0..n).map(|r| gathering_spot(anchor, r)).collect();
            let visits: std::collections::HashSet<Vec3<i32>> = (0..n)
                .map(|r| {
                    gathering_spot(anchor, r ^ 1)
                        + Vec3::new(AROUND[r % 8].0, AROUND[r % 8].1, 0)
                })
                .collect();
            let strolls: std::collections::HashSet<Vec3<i32>> =
                (0..n).map(|r| gathering_spot(anchor, r + STROLL_BAND)).collect();
            let mut seen: std::collections::HashMap<Vec3<i32>, usize> =
                std::collections::HashMap::new();
            for senior in 0..n {
                let c = court_seat(anchor, senior, n);
                assert!(!benches.contains(&c), "n={n} senior {senior}: court seat is a bench");
                assert!(
                    !visits.contains(&c),
                    "n={n} senior {senior}: court seat is somebody's visit seat"
                );
                assert!(!strolls.contains(&c), "n={n} senior {senior}: court seat is a stroll");
                if let Some(prev) = seen.insert(c, senior) {
                    panic!("n={n}: seniors {prev} and {senior} share a court seat at {c:?}");
                }
                let d = c - gathering_spot(anchor, senior);
                assert_eq!(
                    d.x.abs().max(d.y.abs()),
                    1,
                    "n={n} senior {senior}: a court seat must be BESIDE the senior's bench"
                );
                assert_eq!(d.z, 0, "and on the same level");
            }
        }
        // A 30-person colony where every colonist rolls a DIFFERENT
        // activity than their neighbours — the worst case for collisions.
        let mut cells: std::collections::HashMap<Vec3<i32>, (u8, usize)> =
            std::collections::HashMap::new();
        for rank in 0..COLONY {
            let act = (rank % 3) as u8; // 0 sit, 1 stroll, 2 visit
            let c = seat(act, rank, rank);
            if let Some(prev) = cells.insert(c, (act, rank)) {
                panic!(
                    "seat collision at {c:?}: act {act} rank {rank} lands on act {} rank {}",
                    prev.0, prev.1
                );
            }
        }
        // ★ ROW 53: THE SAME COLONY WITH COUPLES IN IT. Ranks 0..2n are n
        // courting couples — the even rank is the senior (their own bench)
        // and the odd rank is the junior (beside it) — and everybody else
        // keeps the rotation. Swept over every plausible number of
        // simultaneous couples, because one union per game day plus a
        // two-day courtship means the count is small but not fixed.
        //
        // ★ THE ASSERTION IS SCOPED TO COURT SEATS, AND HONESTLY SO. This
        // scenario ALSO exposes a PRE-EXISTING defect that has nothing to
        // do with this row: the shipped VISIT arm can land on a third
        // party's bench — `visit(23)` is `gathering_spot(22) + (-1,-1)`,
        // which IS `gathering_spot(8)` — and on another visitor's seat
        // (`visit(8) == visit(27)`, `visit(28) == visit(29)`). The pin
        // above this one cannot see it because it gives each rank exactly
        // one activity via `rank % 3`, and 8, 23 and 27 all land on VISIT
        // there. Fixing VISIT needs a global seat assignment, not a local
        // rule (the call site draws per colonist, independently), so it is
        // named here and left for its own row rather than smuggled in.
        for pairs in 0..=6usize {
            let mut cells: std::collections::HashMap<Vec3<i32>, (u8, usize)> =
                std::collections::HashMap::new();
            for rank in 0..COLONY {
                let (act, senior) = if rank < 2 * pairs {
                    // Even = senior at own bench; odd = junior beside them.
                    if rank % 2 == 0 { (0u8, rank) } else { (4u8, rank - 1) }
                } else {
                    ((rank % 3) as u8, rank)
                };
                let c = seat(act, rank, senior);
                if let Some(prev) = cells.insert(c, (act, rank)) {
                    assert!(
                        act != 4 && prev.0 != 4,
                        "with {pairs} couples: a COURT seat collided at {c:?}: act {act} \
                         rank {rank} against act {} rank {}",
                        prev.0,
                        prev.1
                    );
                }
            }
        }
        // And the pathological case the first version actually hit: every
        // colonist strolling while every OTHER colonist sits.
        let mut cells2: std::collections::HashSet<Vec3<i32>> = Default::default();
        for rank in 0..COLONY {
            assert!(cells2.insert(seat(0, rank, rank)), "sit rank {rank} collided");
        }
        for rank in 0..COLONY {
            assert!(
                cells2.insert(seat(1, rank, rank)),
                "stroll rank {rank} landed on an occupied seat — the +24 defect"
            );
        }
        // ROW 53: and every court seat on top of a FULLY seated colony —
        // the strongest form of the theorem above.
        for senior in 0..COLONY {
            assert!(
                !cells2.contains(&seat(4, senior + 1, senior)),
                "court seat for senior {senior} landed on an occupied cell"
            );
        }
        // A stroll must be a WALK: the far band sits well outside the
        // benches (radius 3-5), not on the first ring.
        let stroll = seat(1, 0, 0) - anchor;
        assert!(
            stroll.x.abs().max(stroll.y.abs()) >= 12,
            "a stroll that ends 6 blocks from the plaza is not a walk: {stroll:?}"
        );
        // A visit is BESIDE the host, not on them.
        for rank in 0..12usize {
            assert_ne!(
                seat(2, rank, rank),
                gathering_spot(anchor, rank ^ 1),
                "visit rank {rank} sat in the host's own chair"
            );
        }
    }

    /// ROW 38 (the population loop): the housing equation and every gate,
    /// both directions. The mandate's own words are the assertion: "ONE
    /// COLONIST PER HOUSE, and the population is DETERMINED by housing."
    #[test]
    fn population_is_determined_by_housing_and_every_refusal_names_itself() {
        use common::bastion::ColonyDrive as D;
        let house = |beds: u32, members: Vec<u64>| HouseholdView {
            min: Vec3::new(0, 0, 0),
            max: Vec3::new(4, 4, 4),
            beds,
            members: members
                .into_iter()
                .map(|u| common::uid::Uid(NonZeroU64::new(u).expect("nonzero")))
                .collect(),
        };
        // THE EQUATION: a house with beds is a seat at the table; a region
        // with none houses nobody.
        assert_eq!(
            immigration_target_pop(&[house(2, vec![7]), house(1, vec![]), house(0, vec![])]),
            2,
            "target population is houses WITH BEDS, not regions"
        );
        assert_eq!(immigration_target_pop(&[]), 0);

        let vacant = vec![Vec3::new(10, 10, 5), Vec3::new(2, 2, 5)];
        let mut sorted = vacant.clone();
        sorted.sort_by_key(|c| (c.x, c.y, c.z));

        // POSITIVE: thriving town, empty house, new day → one settler, at
        // the lowest sorted cell (order-independent).
        let v = immigration_verdict(true, D::Expand, 3, 4, &sorted, 9, Some(8));
        assert!(v.fired, "a thriving town with an empty house draws a settler");
        assert_eq!(v.target, Some(Vec3::new(2, 2, 5)), "deterministic target");

        // EVERY REFUSAL, NAMED — the daily witness prints these, so a
        // silent no-op and a correct decline can never look alike.
        assert_eq!(
            immigration_verdict(false, D::Expand, 3, 4, &sorted, 9, Some(8)).deciding,
            "disabled"
        );
        assert_eq!(
            immigration_verdict(true, D::Expand, 3, 4, &sorted, 9, Some(9)).deciding,
            "same_day",
            "one arrival per game day, latched"
        );
        for d in [D::Grow, D::Sustain, D::Defend] {
            let r = immigration_verdict(true, d, 3, 4, &sorted, 9, Some(8));
            assert!(!r.fired, "{d:?} must not grow the town");
            assert_eq!(r.deciding, "drive_not_expand");
        }
        assert_eq!(
            immigration_verdict(true, D::Expand, 4, 4, &sorted, 9, Some(8)).deciding,
            "roster_at_target",
            "full houses mean no room — the ruling's own ceiling"
        );
        assert_eq!(
            immigration_verdict(true, D::Expand, 9, 4, &sorted, 9, Some(8)).deciding,
            "roster_at_target",
            "over target (a house lost) still refuses, never underflows"
        );
        assert_eq!(
            immigration_verdict(true, D::Expand, 3, 4, &[], 9, Some(8)).deciding,
            "no_vacant_house"
        );
        // FALLBACK IS IDENTITY: disabled refuses every case that would
        // otherwise fire — asserted, not assumed.
        for day_last in [None, Some(8)] {
            assert!(
                !immigration_verdict(false, D::Expand, 0, 9, &sorted, 9, day_last).fired,
                "with the feature off, nothing can arrive"
            );
        }
        // Day 0 is a real day, not "already fired".
        assert!(immigration_verdict(true, D::Expand, 0, 1, &sorted, 0, None).fired);
    }

    /// ROW 36b: the evening palette is weighted as designed, deterministic
    /// on its inputs, and VARIED across days for one person — the pin that
    /// keeps evenings a life, not a loop.
    #[test]
    fn evening_palette_is_weighted_deterministic_and_varied() {
        let (mut sit, mut stroll, mut visit, mut home) = (0, 0, 0, 0);
        for uid in 1..=1000u64 {
            match evening_activity(uid, 5) {
                0 => sit += 1,
                1 => stroll += 1,
                2 => visit += 1,
                _ => home += 1,
            }
        }
        assert!((300..=500).contains(&sit), "sit ~40%: {sit}");
        assert!((200..=400).contains(&stroll), "stroll ~30%: {stroll}");
        assert!((120..=280).contains(&visit), "visit ~20%: {visit}");
        assert!((40..=170).contains(&home), "home ~10%: {home}");
        assert_eq!(
            evening_activity(724, 9),
            evening_activity(724, 9),
            "deterministic"
        );
        let firsts: std::collections::HashSet<u8> =
            (0..10u64).map(|d| evening_activity(724, d)).collect();
        assert!(
            firsts.len() >= 2,
            "ten evenings must not all look the same for one colonist"
        );
    }

    /// ROW 35: the muster scales with the threat and never breaks Ben's
    /// principle — both directions, degenerate corners pinned.
    #[test]
    fn muster_cap_scales_with_threat_but_the_colony_stays_a_colony() {
        assert_eq!(threat_scaled_muster_cap(1, 8), 2, "one group: the old cap");
        assert_eq!(threat_scaled_muster_cap(2, 8), 4, "two groups: four");
        assert_eq!(
            threat_scaled_muster_cap(3, 8),
            4,
            "three groups: CEILING half the militia — never everyone"
        );
        assert_eq!(threat_scaled_muster_cap(3, 7), 4, "ceil(7/2)=4");
        assert_eq!(threat_scaled_muster_cap(5, 3), 2, "small militia: ceil(3/2)=2");
        assert_eq!(
            threat_scaled_muster_cap(3, 0),
            2,
            "militia-less perceiver fallback: identity with the old cap"
        );
        assert_eq!(threat_scaled_muster_cap(0, 8), 2, "no spots still floors at 2");
        // ★ THE REGRESSION THIS PIN ONCE BLESSED (v1 asserted militia==1 ⇒ 1
        // and never tested militia==2 — the modal small town). A scaling
        // rule may only ever ADD defenders: never below the flat cap of 2
        // it replaced, and never non-monotonic in militia.
        for militia in 0..=12usize {
            for spots in 0..=4usize {
                let cap = threat_scaled_muster_cap(spots, militia);
                assert!(
                    cap >= 2,
                    "militia={militia} spots={spots} gave {cap}: below the pre-row-35 cap"
                );
            }
        }
        assert_eq!(threat_scaled_muster_cap(1, 2), 2, "two guards still answer as two");
        assert_eq!(threat_scaled_muster_cap(3, 2), 2, "two guards cannot become one");
        for m in 0..12usize {
            assert!(
                threat_scaled_muster_cap(3, m) <= threat_scaled_muster_cap(3, m + 1),
                "recruiting a guard must never shrink the response (militia {m}→{})",
                m + 1
            );
        }
    }

    /// ROW 35b: cry clusters — tight cries stay ONE post (identity with
    /// row 33), split cries produce both poles' centroids, deterministic.
    #[test]
    fn cry_clusters_split_only_when_vectors_disagree() {
        assert_eq!(split_cry_clusters(&[], 24), None, "no cries, no posts");
        let tight = [
            Vec3::new(2790, 7370, 181),
            Vec3::new(2794, 7365, 181),
            Vec3::new(2792, 7368, 181),
        ];
        let one = split_cry_clusters(&tight, 24).expect("some");
        assert!(one.1.is_none(), "tight cries: one post, as row 33 shipped");
        assert_eq!(one.0, Vec3::new(2792, 7367, 181), "the centroid");
        let split = [
            Vec3::new(2790, 7370, 181),
            Vec3::new(2794, 7365, 181),
            Vec3::new(2950, 7200, 181),
            Vec3::new(2954, 7204, 181),
        ];
        let two = split_cry_clusters(&split, 24).expect("some");
        let b = two.1.expect("two vectors ⇒ two posts");
        assert_eq!(two.0, Vec3::new(2792, 7367, 181), "west cluster centroid");
        assert_eq!(b, Vec3::new(2952, 7202, 181), "east cluster centroid");
        assert_eq!(
            split_cry_clusters(&split, 24),
            split_cry_clusters(&split, 24),
            "deterministic"
        );
    }

    /// ROW 29 (THE DOOR FIGHT): every gate must pass and expiry must
    /// release — a hold that never lets go turns raids into free wins,
    /// and a hold without an occupant besieges empty houses.
    #[test]
    fn a_door_holds_only_while_sheltered_and_gives_way_on_time() {
        assert!(door_fight_holds(true, true, 0.0));
        assert!(door_fight_holds(true, true, DOOR_FIGHT_SECS - 0.1));
        assert!(!door_fight_holds(false, true, 0.0), "no door, no hold");
        assert!(
            !door_fight_holds(true, false, 0.0),
            "an empty house is not defended — the raider passes"
        );
        assert!(
            !door_fight_holds(true, true, DOOR_FIGHT_SECS),
            "the door gives way ON time — a permanent hold is a free win"
        );
    }

    /// ROW 28: the chord walker is SUPERCOVER — grazed corners are the
    /// entire bug (62% of embeds at one clipped building corner), so an
    /// exact-diagonal chord must include BOTH corner neighbours; plain
    /// Bresenham steps past them and a planted naive walker fails here.
    #[test]
    fn chord_cells_are_supercover_so_grazed_corners_are_seen() {
        let a = Vec3::new(0, 0, 5);
        let line = cells_on_chord(a, Vec3::new(3, 0, 5));
        assert_eq!(
            line,
            vec![
                Vec3::new(0, 0, 5),
                Vec3::new(1, 0, 5),
                Vec3::new(2, 0, 5),
                Vec3::new(3, 0, 5),
            ]
        );
        let diag = cells_on_chord(a, Vec3::new(2, 2, 5));
        for c in [
            Vec3::new(1, 0, 5),
            Vec3::new(0, 1, 5),
            Vec3::new(2, 1, 5),
            Vec3::new(1, 2, 5),
            Vec3::new(1, 1, 5),
            Vec3::new(2, 2, 5),
        ] {
            assert!(
                diag.contains(&c),
                "supercover must include {c:?} — got {diag:?}"
            );
        }
        let off = cells_on_chord(a, Vec3::new(4, 2, 5));
        assert_eq!(off.first(), Some(&a));
        assert_eq!(off.last(), Some(&Vec3::new(4, 2, 5)));
        for w in off.windows(2) {
            let d = (w[1] - w[0]).map(|e| e.abs());
            assert!(
                d.x <= 1 && d.y <= 1,
                "chord walk must step to neighbours: {w:?}"
            );
        }
    }

    /// ROW 27 (NIGHT WATCH): the schedule-offset source. Both directions:
    /// offset 0 is the IDENTITY (fallback-must-be-identity — every
    /// non-watch colonist bit-identical to before), the night watch's
    /// work block covers the raid hours, the 8/8/8 totals survive any
    /// rotation, and the planted wrong-sign defect (hour+offset instead
    /// of hour-offset) is caught by the 2am pin.
    #[test]
    fn night_watch_offset_rotates_the_day_without_changing_its_shape() {
        for h in 0..24 {
            assert_eq!(
                schedule_block_at(0, h),
                default_schedule_block(h),
                "offset 0 must be the identity at hour {h}"
            );
        }
        // The watchman WORKS the raid hours (663 died at wall-clock 2am).
        for h in [22, 23, 0, 1, 2, 3, 4, 5] {
            assert_eq!(
                schedule_block_at(NIGHT_WATCH_OFFSET, h),
                ScheduleBlock::Work,
                "night watch works wall hour {h}"
            );
        }
        // He sleeps the afternoon (12-19) and is NOT asleep at his post.
        for h in [12, 15, 19] {
            assert_eq!(
                schedule_block_at(NIGHT_WATCH_OFFSET, h),
                ScheduleBlock::Sleep,
                "night watch sleeps wall hour {h}"
            );
        }
        // The rotated day keeps the exact 8/8/8 shape for ANY offset.
        for off in [NIGHT_WATCH_OFFSET, 1, 7, 23] {
            let (mut s, mut w, mut l) = (0, 0, 0);
            for h in 0..24 {
                match schedule_block_at(off, h) {
                    ScheduleBlock::Sleep => s += 1,
                    ScheduleBlock::Work => w += 1,
                    ScheduleBlock::Leisure => l += 1,
                }
            }
            assert_eq!((s, w, l), (8, 8, 8), "offset {off} broke the 8/8/8 day");
        }
        // Planted defect (wrong sign): hour PLUS offset puts 2am in
        // Leisure, not Work — the raid-hours pin above must catch a
        // future sign flip, so prove the wrong sign actually differs.
        let wrong = default_schedule_block((2 + NIGHT_WATCH_OFFSET) % 24);
        assert_ne!(
            wrong,
            ScheduleBlock::Work,
            "the wrong-sign rotation must be distinguishable at 2am, or the pin pins nothing"
        );
    }

    /// ★ WALKING IS THE DEFAULT GAIT (Ben RULED, in caps): the travel
    /// factor must sit in the villager stroll band, the emergency factor
    /// must remain a true sprint, and the gap must be big enough that an
    /// emergency READS as one. A future retune that nudges travel back
    /// into the jog band re-reds this without any live run.
    #[test]
    fn a_colonist_walks_by_default_and_sprints_only_in_emergencies() {
        assert!(
            TRAVEL_SPEED <= 0.5,
            "default travel ({TRAVEL_SPEED}) must be a WALK — 0.8 rendered as              the colony-wide sprint Ben called out"
        );
        assert!(
            RUN_SPEED >= 1.0,
            "the emergency gait stays a full sprint"
        );
        assert!(
            RUN_SPEED >= TRAVEL_SPEED * 2.0,
            "an emergency must READ as one — at least double the stroll"
        );
    }

    /// ★ SEASONAL TILLING (Ben RULED: "till once ie per growing season"),
    /// both directions: the boundary brings exactly one till obligation per
    /// column; inside a season soil sows freely; and FIRST SIGHT is grace —
    /// an adopted village's fields (or a fresh paint) plant immediately, so
    /// the ruling can never resurrect the till-storm it replaced.
    #[test]
    fn a_column_tills_once_per_season_and_sows_the_rest_of_it() {
        use SeasonalTillVerdict as V;
        // First sight: grace, never a till-storm at adoption.
        assert_eq!(seasonal_till_verdict(None, 40), V::SowGrace);
        // Same season: sow all season long.
        assert_eq!(seasonal_till_verdict(Some(40), 40), V::Sow);
        // The boundary: exactly one till comes due.
        assert_eq!(
            seasonal_till_verdict(Some(40), 41),
            V::Till,
            "a new season brings the once-per-season till"
        );
        // A skipped year still resolves to one till, not a backlog.
        assert_eq!(seasonal_till_verdict(Some(36), 41), V::Till);

        // The index itself: same season+year collapses, next season and
        // NEXT YEAR'S same season both differ (this spring != last spring).
        let year = common::resources::DAY
            * common::time::SeasonConfig::current().days_in_year;
        let spring_y0 = farm_season_index(0.05 * year);
        let spring_y0_later = farm_season_index(0.08 * year);
        let summer_y0 = farm_season_index(0.30 * year);
        let spring_y1 = farm_season_index(1.05 * year);
        assert_eq!(spring_y0, spring_y0_later, "one season, one obligation");
        assert_ne!(spring_y0, summer_y0, "seasons are distinct obligations");
        assert_ne!(
            spring_y0, spring_y1,
            "THIS spring and NEXT spring are different tilling obligations"
        );
    }

    /// ★★ THE BAG GUARD'S THREE GRAVES, all pinned (narrator sweep,
    /// 2026-08-23): v1 protected your own meal from you; v2 let ground
    /// meals be sniped (separate mechanism, separate row); v3 def-locked
    /// hungry colonists against EACH OTHER — four pinned at hunger 0.0000
    /// beside 135 stored meals. The law that survives: nothing anyone ELSE
    /// claims can bind MY inventory; my own material cargo is the sole
    /// bag-protectee.
    #[test]
    fn my_bag_answers_to_my_cargo_and_nobody_elses_claims() {
        let me = Uid(NonZeroU64::new(11).unwrap());
        let other = Uid(NonZeroU64::new(12).unwrap());
        let mut board = JobBoard::default();

        // My in-flight material cargo: a claimed job carrying mushrooms.
        let cargo_id = board.insert_rest_job(Vec3::new(1, 1, 1), me); // shape donor
        {
            let j = board.jobs.get_mut(&cargo_id).unwrap();
            j.kind = common::bastion::JobKind::Haul {
                item: other, // arbitrary uid; kind just must be material
                destination: 0,
            };
            j.required_item = Some("common.items.food.mushroom");
        }
        // My own EatFrom (v1's grave): its def must NOT protect.
        let my_eat = board.insert_eat_job(other, Vec3::new(2, 2, 2), me, 1, "common.items.food.apple");
        let _ = my_eat;
        // ANOTHER colonist's EatFrom on cheese (v3's grave): no claim on me.
        let their_eat =
            board.insert_eat_job(other, Vec3::new(3, 3, 3), other, 2, "common.items.food.cheese");
        let _ = their_eat;

        let protected = cargo_protected_defs(board.jobs.values(), Some(me));
        assert!(
            protected.contains("common.items.food.mushroom"),
            "my own in-flight cargo is protected from my appetite"
        );
        assert!(
            !protected.contains("common.items.food.apple"),
            "v1's grave: my own meal must never be protected from me"
        );
        assert!(
            !protected.contains("common.items.food.cheese"),
            "v3's grave: another colonist's reservation is no claim on MY bag —              this exact case starved four colonists beside a full pantry"
        );
        // And nobody = nothing: an unresolvable uid protects nothing.
        assert!(cargo_protected_defs(board.jobs.values(), None).is_empty());
    }

    /// ★ GOAL-VERDICT pins (PREREG-GOAL-VERDICT-FEEDBACK), all four
    /// registered cases: block while live, expire on the TTL clock,
    /// overwrite (never accumulate), and the disabled gate admits
    /// everything. Env-free impl so both gate states are exercised without
    /// racing the process-wide OnceLock.
    #[test]
    fn a_goal_verdict_blocks_while_live_and_expires_on_its_own_clock() {
        let cell = Vec3::new(5, 5, 10);
        let mut v: HashMap<Vec3<i32>, u64> = HashMap::default();
        v.insert(cell, 1_000);

        assert!(
            goal_verdict_blocks_impl(&v, cell, 999, true),
            "a live verdict blocks its cell"
        );
        assert!(
            !goal_verdict_blocks_impl(&v, cell, 1_000, true),
            "at the expiry tick the verdict is DEAD — it expires on its own              clock, never waits for an amnesty (the E2 law)"
        );
        assert!(
            !goal_verdict_blocks_impl(&v, Vec3::new(6, 5, 10), 999, true),
            "a verdict is goal-keyed: the neighbouring cell is untouched"
        );
        assert!(
            !goal_verdict_blocks_impl(&v, cell, 999, false),
            "gate OFF admits everything — the default until the fleet A/B passes"
        );

        // Overwrite, never accumulate: re-recording the same cell replaces
        // the expiry (additive-capped by construction).
        v.insert(cell, 500);
        assert!(!goal_verdict_blocks_impl(&v, cell, 700, true));
        assert_eq!(v.len(), 1, "one entry per cell, always");
    }

    /// ★ THE FAIL-OPEN TWO-PASS: refusal must never starve the protectee.
    /// Both directions — the respecting pick wins when it can, and an
    /// all-blocked table falls open rather than returning nothing.
    #[test]
    fn a_verdict_pick_prefers_clean_but_never_starves() {
        // A clean candidate exists: the respecting pass wins.
        let got = pick_fail_open(|respect| if respect { Some("clean") } else { Some("any") });
        assert_eq!(got, Some("clean"), "a clean candidate is preferred");
        // Everything blocked: the pick falls open instead of starving.
        let got = pick_fail_open(|respect| if respect { None } else { Some("blocked-but-only") });
        assert_eq!(
            got,
            Some("blocked-but-only"),
            "when every candidate is verdict-blocked the pick proceeds ungated              — a starving colonist still tries the least-bad meal"
        );
        // Nothing at all: still nothing (fail-open is not fabrication).
        let got: Option<&str> = pick_fail_open(|_| None);
        assert_eq!(got, None);
    }

    /// ★ ROW 2: flee an ATTACK, not an existence. The middle case is the
    /// 339-preempt defect verbatim: hostile perceived, no aggro, and the
    /// old predicate fled. Both directions — the flee that saves lives
    /// (aggroed hostile) must survive the narrowing.
    #[test]
    fn a_colonist_flees_an_attack_not_an_existence() {
        assert!(
            flee_worthy_target(true, true),
            "an aggroed hostile still triggers flee — narrowing must not kill              the flee that saves lives"
        );
        assert!(
            !flee_worthy_target(true, false),
            "a hostile that merely entered perception range is not worth              abandoning work for: this exact case fired 339 times at              health=1.0 in one leg"
        );
        assert!(!flee_worthy_target(false, false));
        assert!(!flee_worthy_target(false, true), "aggro from a non-hostile is not flight-worthy");
    }

    /// ★ THE WOUNDED FREEZE SPIRAL (slot-107 soak): pinned BOTH directions.
    /// Pre-fix, `flee_hurt` ignored hostiles entirely, so a wound below
    /// `flee_health` froze the colonist permanently (Flee floor 0.8 wins
    /// arbiter ties; no aggro target = no flee vector = speed 0; travel
    /// refusal starves their own EatFrom, so the wound can never heal shut).
    #[test]
    fn a_wounded_colonist_flees_a_seen_hostile_not_an_empty_field() {
        // The defect face: hurt, NOTHING hostile anywhere → must not flee.
        assert!(
            !flee_hurt_signal(false, 0.2, 0.25),
            "a wound with no hostile in sight is a reason to eat and rest,              not a permanent flee that freezes the colonist where it stands              (slot-107: three of seven frozen 30+ min, fed decayed 8/8 → 5/7)"
        );
        // The comment's own contract survives: hurt waives AGGRO, not the
        // hostile — a merely-SEEN hostile still routs a wounded colonist.
        assert!(
            flee_hurt_signal(true, 0.2, 0.25),
            "hurt + seen hostile must still flee: the aggro waiver is the              whole point of the flee_hurt arm"
        );
        // Healthy colonists ignore a seen-but-unaggroed hostile (that is
        // flee_worthy_target's lane, pinned above at 339 false preempts).
        assert!(!flee_hurt_signal(true, 0.9, 0.25));
        // Boundary: at exactly flee_health the colonist holds (strict <).
        assert!(!flee_hurt_signal(true, 0.25, 0.25));
    }

    /// ★ WEDGED vs PAUSED (mega-city census): the old census counted ANY
    /// sampled instant of `Traveling && speed < 0.2` as stuck — a corner
    /// pause read the same as a 30-minute wedge. Both directions pinned so
    /// neither count can silently absorb the other again.
    #[test]
    fn a_corner_pause_is_slowed_and_a_wedge_is_stuck() {
        // 2s at a corner (the mega-city samples: stuck_time ≈ 1.8-2.7s,
        // best_dist improving) is congestion, not a defect.
        assert!(census_is_slowed(0.1, 2.0));
        assert!(!census_is_wedged(0.1, 2.0));
        // 8s pressed against a wall (recorder territory: STUCK_TIMEOUT=10s
        // releases at 10) is wedged and must show as stuck BEFORE release.
        assert!(census_is_wedged(0.1, 8.0));
        assert!(!census_is_slowed(0.1, 8.0));
        // Moving at speed is neither, whatever the clock says.
        assert!(!census_is_wedged(1.5, 8.0));
        assert!(!census_is_slowed(1.5, 2.0));
        // The two are exhaustive and disjoint over the slow band.
        assert!(census_is_slowed(0.1, CENSUS_WEDGED_SECS));
        assert!(census_is_wedged(0.1, CENSUS_WEDGED_SECS + 0.01));
    }

    /// ★ HOUSEHOLDS v1 (Ben: dedicated owners, families 1-6 by real beds,
    /// take-over on death): derivation is pure and pinned here; take-over
    /// is emergent from the owner-liveness sweep + the vacancy surcharge.
    #[test]
    fn households_derive_from_regions_beds_and_owners() {
        use common::bastion::{BedKind, BedSlot, DesignationKind as D, Region};
        let u = |n: u64| Uid(NonZeroU64::new(n).unwrap());
        let regions = vec![
            (Region { min: Vec3::new(0, 0, 0), max: Vec3::new(9, 9, 9) }, D::Bed),
            (Region { min: Vec3::new(20, 0, 0), max: Vec3::new(29, 9, 9) }, D::Bed),
            // A farm region must never derive as a house.
            (Region { min: Vec3::new(40, 0, 0), max: Vec3::new(49, 9, 9) }, D::Farm),
        ];
        let mut beds = HashMap::new();
        let slot = |o: Option<Uid>| BedSlot { kind: BedKind::Frame, owner: o, occupant: None };
        beds.insert(Vec3::new(1, 1, 1), slot(Some(u(7))));
        beds.insert(Vec3::new(2, 1, 1), slot(Some(u(3))));
        beds.insert(Vec3::new(3, 1, 1), slot(None));
        beds.insert(Vec3::new(21, 1, 1), slot(None)); // vacant house
        beds.insert(Vec3::new(99, 1, 1), slot(Some(u(9)))); // field bedroll: no house
        let (houses, bed_house) = derive_households(&regions, &beds);
        assert_eq!(houses.len(), 2, "two Bed regions, two households — Farm is not a house");
        assert_eq!(houses[0].beds, 3);
        // Members uid-sorted; head = lowest uid.
        assert_eq!(
            houses[0].members.iter().map(|m| m.0.get()).collect::<Vec<_>>(),
            vec![3, 7],
            "members are uid-sorted so the head of household is deterministic"
        );
        assert!(houses[1].members.is_empty(), "the second house derives VACANT");
        assert!(!bed_house.contains_key(&Vec3::new(99, 1, 1)), "a field bedroll joins no house");
        // Ben's capacity ruling, pinned: 1-6 by real beds.
        assert_eq!(household_capacity(0), 1);
        assert_eq!(household_capacity(3), 3);
        assert_eq!(household_capacity(9), 6);
    }

    /// ★ THE SURCHARGE, BOTH DIRECTIONS: a vacant house wins up to 2x the
    /// walking distance; past that the near shared bed wins — the 186-block
    /// nearest-bed lesson must survive the vacancy preference.
    #[test]
    fn a_vacant_house_wins_nearby_and_loses_across_town() {
        let feet = Vec3::new(0, 0, 0);
        // Occupied-house bed 10 blocks out vs vacant-house bed 15 blocks out:
        // 15 < 2x10, vacant wins.
        let near_occupied = bed_claim_cost(bed_assignment_cost(Vec3::new(10, 0, 0), feet), Some(1));
        let mid_vacant = bed_claim_cost(bed_assignment_cost(Vec3::new(15, 0, 0), feet), Some(0));
        assert!(
            mid_vacant < near_occupied,
            "a modest detour to a house of one's own beats moving in with a stranger"
        );
        // Occupied bed 10 blocks vs vacant 186 blocks: the disaster distance
        // loses — nobody crosses the whole town for an empty house.
        let far_vacant = bed_claim_cost(bed_assignment_cost(Vec3::new(186, 0, 0), feet), Some(0));
        assert!(
            near_occupied < far_vacant,
            "the 186-block lesson holds: distance still dominates at town scale"
        );
        // A field bedroll (no house) carries the surcharge too: a roof beats
        // a field at equal distance.
        let field = bed_claim_cost(bed_assignment_cost(Vec3::new(15, 0, 0), feet), None);
        assert!(mid_vacant < field, "same distance: the house bed wins over the field bedroll");
    }

    /// ★ CITY RINGS (Ben's screenshot: ~30 colonists stacked in one plaza
    /// blob). The village pin proved 12 seats for 12; this is the same
    /// falsifier at city scale — mod-12 wrap FAILED it by construction.
    #[test]
    fn the_city_plaza_seats_a_whole_city_without_stacking() {
        let anchor = Vec3::new(100, 100, 50);
        let seats: Vec<Vec3<i32>> = (0..96).map(|r| gathering_spot(anchor, r)).collect();
        let distinct: HashSet<Vec3<i32>> = seats.iter().copied().collect();
        assert_eq!(
            distinct.len(),
            96,
            "ninety-six lounging colonists get ninety-six distinct seats — the             mega-city blob was 44 ranks wrapped onto 12 benches"
        );
        // The village's first twelve benches are byte-identical (banked runs).
        assert_eq!(gathering_spot(anchor, 0), anchor + Vec3::new(3, 0, 0));
        assert_eq!(gathering_spot(anchor, 11), anchor + Vec3::new(-1, -5, 0));
        // Nobody seats ON the anchor and nobody drifts absurdly far.
        for (r, s) in seats.iter().enumerate() {
            let d = (*s - anchor).xy().map(|e| e.abs());
            assert!(d.x.max(d.y) >= 2, "rank {r} seated inside the anchor cell");
            assert!(d.x.max(d.y) <= 16, "rank {r} seated {d:?} — outside any plausible plaza");
        }
    }

    /// ★ BUILDING PURPOSES consumer 1 — the venue split. Both directions:
    /// venues share the crowd collision-free, and no-taverns degrades to
    /// exactly the single-plaza behavior every banked run pinned.
    #[test]
    fn taverns_split_the_evening_and_no_tavern_changes_nothing() {
        // V=1 (no taverns): identity — venue 0, rank unchanged, for all.
        for r in 0..40 {
            assert_eq!(venue_and_rank(r, 1), (0, r));
        }
        // V=3 (plaza + two taverns): every venue used, within-ranks
        // compact and collision-free per venue.
        let mut per_venue: HashMap<usize, Vec<usize>> = HashMap::new();
        for r in 0..30 {
            let (v, w) = venue_and_rank(r, 3);
            per_venue.entry(v).or_default().push(w);
        }
        assert_eq!(per_venue.len(), 3, "all three venues get regulars");
        for (v, ws) in per_venue {
            assert_eq!(
                ws,
                (0..10).collect::<Vec<_>>(),
                "venue {v}'s within-ranks must be compact 0..n — a gap or                 repeat re-creates the seat collision the ring was built to kill"
            );
        }
        // Degenerate guard: zero venues clamps to one, never divides by zero.
        assert_eq!(venue_and_rank(7, 0), (0, 7));
    }

    /// ★ A CREW, NOT A STAMPEDE + WORK NEAR HOME (Ben, live in the city).
    #[test]
    fn a_paint_crew_is_a_sixth_and_home_pull_favours_the_neighbour() {
        // 48 colonists send a crew of 8; a hamlet of 8 sends 2; never fewer.
        assert_eq!(player_paint_crew_cap(48), 8);
        assert_eq!(player_paint_crew_cap(8), 2);
        assert_eq!(player_paint_crew_cap(3), 2);
        // The neighbour outbids the cross-town colonist at equal standing
        // distance: 10 blocks from home vs 100 adds 5 vs 50 to the score.
        let job = Vec3::new(50, 50, 0);
        let near = home_pull_penalty(Some(Vec3::new(50, 40, 0)), job);
        let far = home_pull_penalty(Some(Vec3::new(50, 150, 0)), job);
        assert!(near < far);
        assert!((near - 5.0).abs() < 0.01, "half-weighted: 10 blocks from home adds 5");
        // The homeless carry no penalty — housing them is the assigner's
        // job, not the scorer's to punish.
        assert_eq!(home_pull_penalty(None, job), 0.0);
    }

    /// ★ THE BED LEAK (805bf30a06), RED PRE-FIX: the suspend path sets
    /// `claimed_by = None` and parks the owner in `suspended_for`, so
    /// `remove_job`'s release guard (`occupant == claimed_by`) compared
    /// `Some(u) == None`, never matched, and left `occupant` set on a
    /// DELETED job — the colonist's own bed then read as occupied to
    /// ITSELF and it was steered to the nearest free bed instead.
    #[test]
    fn a_suspended_rest_job_removed_still_frees_its_bed() {
        use common::bastion::{BedKind, BedSlot};
        let u = Uid(NonZeroU64::new(11).unwrap());
        let bed = Vec3::new(5, 5, 10);
        let mut board = JobBoard::default();
        board.beds.insert(bed, BedSlot {
            kind: BedKind::Frame,
            owner: Some(u),
            occupant: Some(u),
        });
        let id = board.insert_rest_job(bed, u);
        // The suspend transition, exactly as the preemption path writes it.
        {
            let j = board.jobs.get_mut(&id).unwrap();
            j.claimed_by = None;
            j.suspended_for = Some(u);
        }
        board.remove_job(id);
        assert_eq!(
            board.beds[&bed].occupant, None,
            "a suspended RestAt removed from the board must free its bed:              pre-fix the guard compared occupant against claimed_by (None) and              the occupant leaked forever, locking the owner out of their own bed"
        );

        // The other direction: custody held by ANOTHER colonist's live
        // claim must survive this job's removal — a re-assigned bed is the
        // other job's to free, and an over-eager clear would evict a real
        // sleeper.
        let v = Uid(NonZeroU64::new(12).unwrap());
        let id2 = board.insert_rest_job(bed, u);
        {
            let j = board.jobs.get_mut(&id2).unwrap();
            j.claimed_by = None;
            j.suspended_for = Some(u);
        }
        board.beds.get_mut(&bed).unwrap().occupant = Some(v);
        board.remove_job(id2);
        assert_eq!(
            board.beds[&bed].occupant,
            Some(v),
            "another colonist's occupancy is not this job's custody to clear"
        );
    }

    /// ★ THE BOARD IS SESSION-STATE; THE RECORD IS TRUTH (805bf30a06).
    /// After a reload the board's `owner` fields are gone while every
    /// colonist record still names its bed — pre-fix the assigner read
    /// "homeless" from the board and re-paired the whole colony from
    /// wherever it stood.
    #[test]
    fn bed_ownership_replays_from_the_records_after_a_reload() {
        use common::bastion::{BedKind, BedSlot};
        let empty_slot = |owner| BedSlot { kind: BedKind::Frame, owner, occupant: None };
        let a = Uid(NonZeroU64::new(11).unwrap());
        let b = Uid(NonZeroU64::new(12).unwrap());
        let c = Uid(NonZeroU64::new(13).unwrap());
        let bed_a = Vec3::new(1, 0, 0);
        let bed_b = Vec3::new(2, 0, 0);
        let mut beds = HashMap::default();
        beds.insert(bed_a, empty_slot(None));
        beds.insert(bed_b, empty_slot(Some(c))); // live assignment survives

        replay_bed_ownership(&mut beds, vec![
            // Deliberately unsorted: determinism must come from the sort
            // inside, not from the caller's join order.
            (b, bed_b),
            (a, bed_a),
            // A record naming a bed the board no longer knows: no-op, the
            // stale-record sweep clears it later.
            (c, Vec3::new(99, 99, 99)),
        ]);

        assert_eq!(
            beds[&bed_a].owner,
            Some(a),
            "an amnesiac board must relearn ownership from the colonist record"
        );
        assert_eq!(
            beds[&bed_b].owner,
            Some(c),
            "a live owner is never overwritten by a stale record"
        );

        // Double-claim: two records naming ONE bed resolve by uid order,
        // identically on every run — the loser stays homeless this pass.
        let mut beds2 = HashMap::default();
        beds2.insert(bed_a, empty_slot(None));
        replay_bed_ownership(&mut beds2, vec![(b, bed_a), (a, bed_a)]);
        assert_eq!(
            beds2[&bed_a].owner,
            Some(a),
            "a double-claim resolves to the lower uid, not the join order"
        );
    }

    /// ★ SLEEP HOLDS ONLY AT THE BED (805bf30a06): rest accrued from a
    /// proximity latch set ONCE at arrival — "a sleep from 6 blocks away
    /// and a sleep in the bed log byte-identically" (proven: pure decay to
    /// four decimals against zero recovery). Both directions: displacement
    /// must stop the banking, and the guard must not evict a body that is
    /// actually on the bed (hysteresis band: release only past
    /// ARRIVE_DIST + 0.5, so boundary jitter cannot flap the state).
    #[test]
    fn sleep_stops_banking_when_the_body_leaves_the_bed() {
        let bed = Vec3::new(10, 10, 5);
        // Where the BODY lies: the bed is a feet cell, so no z offset (see
        // `lying_target`). Written as a literal, not derived.
        let centre = Vec3::new(10.5, 10.5, 5.0);
        // On the bed: never displaced.
        assert!(!sleep_displaced(centre, bed), "lying on the bed is not displaced");
        // Inside the hysteresis band (between ARRIVE_DIST and +0.5): still
        // held — this is what keeps physics jitter from flapping the state.
        assert!(
            !sleep_displaced(centre + Vec3::new(ARRIVE_DIST + 0.4, 0.0, 0.0), bed),
            "jitter at the arrival boundary must not evict the sleeper"
        );
        // The proven defect, exactly: banking rest from 6 blocks away.
        assert!(
            sleep_displaced(centre + Vec3::new(6.0, 0.0, 0.0), bed),
            "a body 6 blocks from the bed must stop banking rest — this exact              case logged byte-identically to real sleep pre-fix"
        );
        // Displacement is 3D — a body shoved a storey below the bed is off it.
        assert!(sleep_displaced(centre - Vec3::new(0.0, 0.0, 4.0), bed));
    }

    #[test]
    fn designated_sweep_reaps_only_unclaimed_designated_past_threshold() {
        // ITEM8-V4 route 3, RED PRE-FIX: this sweep did not exist before
        // this row -- every one of these true cases is new coverage, not
        // a regression pin on prior behavior.
        const T: f64 = 10.0;
        // The one case that should sweep: unclaimed, Designated, at or
        // past the threshold.
        assert!(designated_sweep_should_reap(false, true, false, false, T, T));
        assert!(designated_sweep_should_reap(false, true, false, false, T + 1.0, T));
        // Claimed: never swept, regardless of how long it's been
        // "unclaimed" by a stale counter (that would be a double-remove
        // race against the job's own claimant).
        assert!(!designated_sweep_should_reap(true, true, false, false, T + 100.0, T));
        // Not a Designated kind (Haul/RestAt/EatFrom/Despond/DepositRun):
        // out of this sweep's declared scope, never touched.
        assert!(!designated_sweep_should_reap(false, false, false, false, T + 100.0, T));
        // Under threshold: too soon, not yet a backstop case.
        assert!(!designated_sweep_should_reap(false, true, false, false, T - 1.0, T));
        // ★ RENEWABLE EXEMPTION (Ben, 2026-08-23: "so our simulation doesn't
        // get messed up by junk jobs"): a farm job the pass re-derives from
        // cell state next cycle is NEVER reaped, at ANY staleness — reaping
        // it only churns job ids (8,364 created vs ~600 completed in one
        // measured leg, 3,477 reaps). Non-renewables keep the backstop.
        assert!(
            !designated_sweep_should_reap(false, true, true, false, T + 10_000.0, T),
            "a renewable (farm) designation is exempt from the reap forever"
        );
    }

    #[test]
    fn sweep_never_reaps_a_freshly_unclaimed_job_regardless_of_position_history() {
        // ITEM8-V4 route 3 v2, THE TEST THAT WOULD HAVE CAUGHT v4's LIVE
        // FINDING PRE-LAUNCH (Fable's exact ask, filed with that comment):
        // a job's OWN unclaimed duration is 0.0 the instant it's first
        // observed unclaimed, no matter how long some earlier job at the
        // SAME position sat unclaimed before it. The predicate takes
        // `unclaimed_secs` directly -- it has no way to see position
        // history at all, which is the fix: the position-keyed counter
        // (`cycles_since_last_claim`) that caused the 186-reap churn is
        // no longer consulted by this predicate or its caller.
        const T: f64 = 10.0;
        assert!(
            !designated_sweep_should_reap(false, true, false, false, 0.0, T),
            "a job observed unclaimed for the first time this pass (0.0s) must not be reapable, \
             even if a prior job at its position was stale for a long time -- that history \
             belongs to the position, not to this job"
        );
        // A job one arbitration pass old (well under any real threshold)
        // is still safely inside its grace period.
        assert!(!designated_sweep_should_reap(false, true, false, false, 0.5, T));
    }

    #[test]
    fn sweep_still_reaps_a_genuinely_old_unclaimed_job() {
        // ITEM8-V4 route 3 v2: the original intent, preserved by the
        // fix -- a job that has been unclaimed, by ITS OWN clock, for
        // longer than the threshold is still a legitimate backstop case.
        const T: f64 = 10.0;
        assert!(designated_sweep_should_reap(false, true, false, false, T, T));
        assert!(designated_sweep_should_reap(false, true, false, false, 3600.0, T));
    }

    /// ROW 20 (micro-haul treadmill): the chain predicate — the unit of a
    /// haul is the LOAD, not the item. Both directions: the qualifying
    /// shape passes, and every disqualifier flips it ALONE (each planted).
    #[test]
    fn haul_chain_extends_only_unclaimed_same_def_same_zone_nearby_hauls() {
        let def: &'static str = "common.items.food.cheese";
        let other_def: &'static str = "common.items.crafting_ing.stones";
        let feet = Vec3::new(10.5, 10.5, 1.0);
        let base = || Job {
            player_ordered: false,
            kind: common::bastion::JobKind::Haul {
                item: common::uid::Uid(NonZeroU64::new(11).expect("nonzero")),
                destination: 7,
            },
            work: DesignationKind::Stockpile.work_type(),
            pos: Vec3::new(14, 10, 0),
            skill_floor: 0,
            claimed_by: None,
            suspended_for: None,
            unreachable: false,
            progress: 0.0,
            required_item: Some(def),
            needs_materials: false,
            carve_attempted: false,
            is_access: false,
            stuck_strikes: 0,
            benched_until_tick: None,
            depth: 0,
            reservation: None,
            affordance: AffordanceClass::Untargeted,
        };
        assert!(haul_chain_candidate(&base(), 7, def, feet, 100));
        // An EXPIRED bench is eligible again (<=, not <).
        let mut j = base();
        j.benched_until_tick = Some(100);
        assert!(haul_chain_candidate(&j, 7, def, feet, 100));
        let mut j = base();
        j.claimed_by = Some(common::uid::Uid(NonZeroU64::new(3).expect("nonzero")));
        assert!(!haul_chain_candidate(&j, 7, def, feet, 100), "claimed");
        let mut j = base();
        j.suspended_for = Some(common::uid::Uid(NonZeroU64::new(3).expect("nonzero")));
        assert!(!haul_chain_candidate(&j, 7, def, feet, 100), "suspended: still owned");
        let mut j = base();
        j.unreachable = true;
        assert!(!haul_chain_candidate(&j, 7, def, feet, 100), "unreachable");
        let mut j = base();
        j.benched_until_tick = Some(101);
        assert!(!haul_chain_candidate(&j, 7, def, feet, 100), "benched into the future");
        assert!(
            !haul_chain_candidate(&base(), 8, def, feet, 100),
            "a different destination zone would leave the bag's obligation stranded"
        );
        assert!(
            !haul_chain_candidate(&base(), 7, other_def, feet, 100),
            "a different def rides along undeposited — deposit_all_of empties BY DEF"
        );
        let mut j = base();
        j.kind = common::bastion::JobKind::DepositRun { destination: 7 };
        assert!(!haul_chain_candidate(&j, 7, def, feet, 100), "not a Haul");
        let mut j = base();
        j.pos = Vec3::new(23, 10, 0);
        assert!(
            !haul_chain_candidate(&j, 7, def, feet, 100),
            "outside HAUL_CHAIN_RADIUS"
        );
        // Boundary honesty: exactly AT the radius qualifies (<=). stand =
        // (22.5, 10.5, 1.0), feet = (10.5, 10.5, 1.0) → 12.0 = the radius.
        let mut j = base();
        j.pos = Vec3::new(22, 10, 1);
        assert!(haul_chain_candidate(&j, 7, def, feet, 100), "at-radius inclusive");
    }

    #[test]
