    #[test]
    fn verified_emergency_exit_clears_only_the_released_route_movement() {
        let stale_target = Vec3::new(12.5, 8.5, 4.0);
        let fresh_target = Vec3::new(20.5, 18.5, 4.0);
        let mut rtsim_controller = common::rtsim::RtSimController::default();
        rtsim_controller.set_goto_with_endpoint(stale_target, 1.0, 0.75);
        let mut chaser = common::path::Chaser::default();
        let mut controller = comp::Controller::default();
        controller.inputs.move_dir = Vec2::new(0.75, -0.5);
        controller.inputs.move_z = 1.0;

        clear_verified_emergency_exit_movement(
            &mut rtsim_controller,
            &mut chaser,
            Some(&mut controller),
        );

        assert!(rtsim_controller.activity.is_none());
        assert_eq!(rtsim_controller.path_endpoint_tolerance(stale_target), None);
        assert_eq!(controller.inputs.move_dir, Vec2::zero());
        assert_eq!(controller.inputs.move_z, 0.0);

        // Cleanup is an ownership boundary, not a permanent movement lock:
        // the next normal AI pass can install an unrelated fresh activity.
        rtsim_controller.activity = Some(common::rtsim::NpcActivity::Goto(fresh_target, 0.5));
        assert!(matches!(
            rtsim_controller.activity,
            Some(common::rtsim::NpcActivity::Goto(target, 0.5)) if target == fresh_target
        ));
        assert_eq!(rtsim_controller.path_endpoint_tolerance(fresh_target), None);
    }

    /// CASE-003 pin: the fail-safe picker must SKIP a column whose surface
    /// is occupied by a non-surface solid (a tree trunk standing on the
    /// scanned ground) and land on the next clear column — never inside the
    /// trunk. This is the seed-21 wedge: `column_surface_z` sees through
    /// Wood, the old picker teleported the colonist into it.
    #[test]
    fn surface_teleport_skips_occupied_column() {
        // Every column's surface is z=10; a trunk occupies (0,0,11)+(0,0,12).
        let surface_z = |_x: i32, _y: i32| Some(10);
        let open =
            |p: Vec3<i32>| p.z > 10 && !(p.xy() == Vec2::new(0, 0) && (p.z == 11 || p.z == 12));
        let dest = surface_teleport_dest_impl(surface_z, open, Vec3::new(0, 0, 5), 0)
            .expect("clear columns exist in the spiral");
        assert_ne!(dest.xy(), Vec2::new(0, 0), "teleported into the trunk");
        assert_eq!(dest.z, 11);
    }

    /// ★ A DELIVERY LANDS ON THE GROUND, NOT THE PAINTED TOP (the roof
    /// deposit-point): three sites aimed deposits at `(center, r.max.z)`
    /// and the goal snapper put that on the ROOF above a house — 37/45
    /// deliveries to cells nothing could fetch from. Both directions: the
    /// resolved surface wins over the painted top, and an unresolvable
    /// column (open water / unloaded chunk) falls back to the painted
    /// FLOOR — the one z that can never be a roof.
    #[test]
    fn a_deposit_targets_the_ground_never_the_painted_top() {
        // A zone painted as a tall box over a house: floor 10, top 30.
        let zone = Region { min: Vec3::new(0, 0, 10), max: Vec3::new(8, 8, 30) };
        // The surface authority sees through the wooden roof: ground at 10.
        let dest = stockpile_drop_cell_impl(|_, _, _| Some(10), &zone);
        assert_eq!(
            dest,
            Vec3::new(4, 4, 11),
            "the drop cell is the standable cell on the REAL surface — pre-fix              this was (4, 4, 30), which the ±16 goal snap put on the roof"
        );
        // Unresolvable column: painted floor, never the top.
        let dest = stockpile_drop_cell_impl(|_, _, _| None, &zone);
        assert_eq!(
            dest,
            Vec3::new(4, 4, 10),
            "no surface in the window falls back to the painted floor"
        );
        // And the resolver is genuinely consulted with the floor as hint —
        // a sloped site resolves per-column, not from the box geometry.
        let dest = stockpile_drop_cell_impl(
            |x, y, hint| {
                assert_eq!((x, y, hint), (4, 4, 10), "centre column, floor hint");
                Some(14)
            },
            &zone,
        );
        assert_eq!(dest.z, 15);
    }

